  var META = {"id":"fishing-tool-kg","sceneId":"wo2","title":"落物打捞工具智能选型：匹配矩阵"};
  var DEMO = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"设定落物形态、外径 / 内径、长度、井斜、落底三态、材质与卡阻状态，看硬约束先排除哪些工具（工具外径 + 单边间隙、可捞区间、材质、井斜、循环、落底、咬合长度），软评分如何给剩下 11 件打捞工具排序；套铣筒与平底磨鞋只作为解卡 / 磨铣工序出现，不参与打捞排序。","height":760};
  var FILES = [{"name":"demo/demo.css","size":11377,"mime":"text/plain","enc":"text","data":"/* =========================================================\r\n   案例示范页 · 公共皮肤 Demo Base Skin\r\n   ---------------------------------------------------------\r\n   这份文件是「案例包 demo/demo.css」的统一母版：\r\n   tools/build-cases.mjs 会把它原样复制到每个案例包的\r\n   cases/<id>/demo/demo.css，保证所有示范页长得像一家人。\r\n\r\n   示范页运行在 sandbox iframe 里，与主站互不影响，\r\n   因此这里自带一套令牌，不依赖主站的 CSS。\r\n   ========================================================= */\r\n\r\n:root{\r\n  --ink:#1a2428; --ink-2:#4a585c; --ink-3:#6f7a7c; --ink-4:#99a3a4;\r\n  --paper:#f6f2e8; --paper-2:#efe9dd; --paper-3:#e5dcc9;\r\n  --card:#fffefa; --card-soft:#faf7f0;\r\n  --line:#e3dccd; --line-2:#d3c9b6; --line-3:#beb19a;\r\n  --jade:#245c5a; --jade-d:#123a3d; --jade-l:#e7eee9;\r\n  --clay:#a9742c; --clay-d:#83551f; --clay-l:#f4e8d4;\r\n  --ok:#3d7455; --ok-bg:#e8f0e7;\r\n  --warn:#9a6b1d; --warn-bg:#f4e8d4;\r\n  --bad:#a64b3c; --bad-bg:#f7e8e2;\r\n  --cv:#245c5a; --ts:#a9742c; --nlp:#5a6b78; --opt:#355c74; --kg:#6e6a3c;\r\n  --mono:'JetBrains Mono','SFMono-Regular','Cascadia Mono',Consolas,'Liberation Mono',monospace;\r\n  --sans:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei UI','Microsoft YaHei',sans-serif;\r\n}\r\n\r\n*{box-sizing:border-box;margin:0;padding:0}\r\nbody{\r\n  font-family:var(--sans);font-size:13.5px;line-height:1.7;color:var(--ink);\r\n  background:var(--paper);padding:16px 18px 20px;-webkit-font-smoothing:antialiased;\r\n}\r\nb,strong{font-weight:650;color:var(--ink)}\r\n.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}\r\n\r\n/* ---------- 头部 ---------- */\r\n.dhead{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;align-items:start;margin-bottom:12px}\r\n.dhead h1{font-size:17px;letter-spacing:-.01em;line-height:1.3}\r\n.dhead .lead{font-size:12px;color:var(--ink-3);line-height:1.7;margin-top:5px;max-width:76ch}\r\n.dkick{\r\n  font-family:var(--mono);font-size:9px;letter-spacing:.16em;color:var(--jade-d);\r\n  display:inline-flex;align-items:center;gap:7px;margin-bottom:6px;text-transform:uppercase;\r\n}\r\n.dkick::before{content:'';width:16px;height:1.5px;background:currentColor;opacity:.5}\r\n.dhead-r{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end;padding-top:2px}\r\n.dstat{\r\n  border:1px solid var(--line);background:var(--card);border-radius:7px;padding:5px 10px;min-width:74px;\r\n}\r\n.dstat .k{font-family:var(--mono);font-size:8px;letter-spacing:.1em;color:var(--ink-4);white-space:nowrap}\r\n.dstat .v{font-family:var(--mono);font-size:14px;color:var(--ink);line-height:1.35}\r\n.dstat .v small{font-size:8.5px;color:var(--ink-4);margin-left:2px;font-family:var(--sans)}\r\n.dstat.good .v{color:var(--ok)}.dstat.warn .v{color:var(--warn)}.dstat.bad .v{color:var(--bad)}\r\n\r\n/* ---------- 控制条 ---------- */\r\n.dctl{\r\n  display:flex;align-items:center;gap:18px;flex-wrap:wrap;\r\n  padding:10px 13px;border:1px solid var(--line);border-radius:9px;\r\n  background:var(--card-soft);margin-bottom:12px;\r\n}\r\n.dctl .grp{display:flex;align-items:center;gap:8px}\r\n.dctl .glbl{font-family:var(--mono);font-size:8.5px;letter-spacing:.12em;color:var(--ink-4);white-space:nowrap}\r\n.dctl .sp{flex:1}\r\n\r\n.ctl-s{display:flex;align-items:center;gap:8px}\r\n.ctl-s label{font-family:var(--mono);font-size:9px;letter-spacing:.06em;color:var(--ink-3);white-space:nowrap}\r\n.ctl-s output{font-family:var(--mono);font-size:11.5px;color:var(--jade-d);font-weight:600;min-width:38px;text-align:right}\r\ninput[type=range]{\r\n  -webkit-appearance:none;appearance:none;width:132px;height:3px;border-radius:2px;\r\n  background:var(--line-2);outline:none;cursor:pointer;\r\n}\r\ninput[type=range]::-webkit-slider-thumb{\r\n  -webkit-appearance:none;appearance:none;width:14px;height:14px;border-radius:50%;\r\n  background:var(--jade);border:2px solid #fff;box-shadow:0 0 0 1px var(--jade);\r\n}\r\ninput[type=range]::-moz-range-thumb{width:12px;height:12px;border-radius:50%;background:var(--jade);border:2px solid #fff}\r\n\r\n.seg{display:inline-flex;flex-wrap:wrap;border:1px solid var(--line-2);border-radius:5px;background:var(--card);padding:2px;gap:2px;max-width:100%}\r\n.seg button{\r\n  --mc:var(--jade);\r\n  font-family:var(--sans);font-size:11.5px;color:var(--ink-2);padding:4px 11px;border-radius:3px;white-space:nowrap;\r\n  transition:background .15s,color .15s;\r\n}\r\n.seg button:hover{color:var(--ink)}\r\n.seg button.on{background:var(--mc);color:#fff;font-weight:500}\r\n.seg button.on[data-c]{background:var(--mc);color:#fff}\r\n.seg button[data-c=\"cv\"]{--mc:var(--cv)}.seg button[data-c=\"ts\"]{--mc:var(--ts)}\r\n.seg button[data-c=\"nlp\"]{--mc:var(--nlp)}.seg button[data-c=\"opt\"]{--mc:var(--opt)}\r\n.seg button[data-c=\"kg\"]{--mc:var(--kg)}\r\n\r\n.dbtn{\r\n  display:inline-flex;align-items:center;gap:6px;font-size:11.5px;padding:5px 12px;\r\n  border:1px solid var(--line-2);border-radius:100px;background:var(--card);color:var(--ink-2);\r\n  transition:all .15s;cursor:pointer;white-space:nowrap;\r\n}\r\n.dbtn:hover{border-color:var(--line-3);color:var(--ink)}\r\n.dbtn.pri{background:var(--jade);border-color:var(--jade);color:#fff;font-weight:600}\r\n.dbtn.pri:hover{background:var(--jade-d);border-color:var(--jade-d)}\r\n.dbtn:disabled{opacity:.45;cursor:not-allowed;filter:grayscale(.4)}\r\n\r\n.tog{display:inline-flex;align-items:center;gap:7px;cursor:pointer;font-size:11.5px;color:var(--ink-2);user-select:none}\r\n.tog i{width:30px;height:16px;border-radius:9px;background:var(--line-2);position:relative;transition:background .16s;flex-shrink:0}\r\n.tog i::after{content:'';position:absolute;left:2px;top:2px;width:12px;height:12px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.18);transition:transform .16s}\r\n.tog.on i{background:rgba(20,112,92,.45)}\r\n.tog.on i::after{transform:translateX(14px);background:var(--jade-d)}\r\n\r\n/* ---------- 布局 ---------- */\r\n.dgrid{display:grid;gap:12px}\r\n.dgrid.c2{grid-template-columns:minmax(0,1fr) minmax(0,340px)}\r\n.dgrid.c2b{grid-template-columns:minmax(0,340px) minmax(0,1fr)}\r\n.dgrid.c3{grid-template-columns:repeat(3,minmax(0,1fr))}\r\n.dcol{display:flex;flex-direction:column;gap:12px;min-width:0}\r\n.drow{display:flex;gap:12px;flex-wrap:wrap}\r\n\r\n/* ---------- 图框 ---------- */\r\n.dfig{border:1px solid var(--line);border-radius:9px;background:var(--card);padding:10px 11px 8px}\r\n.dfig-h{\r\n  display:flex;align-items:baseline;justify-content:space-between;gap:10px;\r\n  font-family:var(--mono);font-size:8.5px;letter-spacing:.1em;color:var(--ink-4);\r\n  margin-bottom:7px;text-transform:uppercase;\r\n}\r\n.dfig-h b{color:var(--ink-3);font-weight:500;letter-spacing:0;text-transform:none;font-family:var(--sans);font-size:11px}\r\n.dfig svg{display:block;width:100%;height:auto}\r\n.dfig-foot{\r\n  display:flex;gap:12px;flex-wrap:wrap;border-top:1px solid var(--line);\r\n  margin-top:8px;padding-top:7px;font-size:10.5px;color:var(--ink-4);\r\n}\r\n.dfig-foot span{display:flex;align-items:center;gap:5px}\r\n.dfig-foot i{width:13px;height:3px;border-radius:2px;display:block;flex-shrink:0}\r\n.dfig-foot i.dash{height:0;border-top:1.5px dashed var(--jade);background:none!important}\r\n\r\n/* ---------- 读数 / 指标 ---------- */\r\n.dread{display:grid;grid-template-columns:repeat(auto-fit,minmax(96px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:9px;overflow:hidden}\r\n.dread > div{background:var(--card);padding:8px 10px}\r\n.dread .k{font-family:var(--mono);font-size:8px;letter-spacing:.09em;color:var(--ink-4);white-space:nowrap}\r\n.dread .v{font-family:var(--mono);font-size:16px;line-height:1.3;margin-top:2px;color:var(--ink)}\r\n.dread .v small{font-size:8.5px;color:var(--ink-4);margin-left:2px;font-family:var(--sans)}\r\n.dread .v.ok{color:var(--ok)}.dread .v.warn{color:var(--warn)}.dread .v.bad{color:var(--bad)}\r\n\r\n.dnote{\r\n  font-size:11.5px;color:var(--ink-3);line-height:1.7;padding:9px 12px;\r\n  border-left:2.5px solid var(--clay);background:linear-gradient(90deg,rgba(192,118,43,.07),transparent 76%);\r\n  border-radius:0 4px 4px 0;\r\n}\r\n.dnote b{color:var(--ink)}\r\n.dnote.ok{border-left-color:var(--ok);background:linear-gradient(90deg,rgba(61,133,88,.07),transparent 76%)}\r\n.dnote.bad{border-left-color:var(--bad);background:linear-gradient(90deg,rgba(176,84,74,.07),transparent 76%)}\r\n\r\n/* ---------- 徽标 ---------- */\r\n.db{display:inline-flex;align-items:center;gap:5px;font-family:var(--mono);font-size:9.5px;letter-spacing:.05em;padding:2px 8px;border-radius:5px;border:1px solid;white-space:nowrap}\r\n.db.ok{color:var(--ok);border-color:rgba(61,133,88,.28);background:var(--ok-bg)}\r\n.db.warn{color:var(--warn);border-color:rgba(168,121,27,.28);background:var(--warn-bg)}\r\n.db.bad{color:var(--bad);border-color:rgba(176,84,74,.28);background:var(--bad-bg)}\r\n.db.plain{color:var(--ink-3);border-color:var(--line-2);background:var(--card-soft)}\r\n.db::before{content:'';width:4px;height:4px;border-radius:50%;background:currentColor}\r\n\r\n/* ---------- 列表 / 卡片 ---------- */\r\n.dcard{border:1px solid var(--line);border-radius:9px;background:var(--card);padding:10px 12px}\r\n.dcard + .dcard{margin-top:7px}\r\n.dcard h4{font-size:12.5px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}\r\n.dcard p{font-size:11px;color:var(--ink-3);line-height:1.6;margin-top:4px}\r\n.dcard .top{display:flex;align-items:baseline;justify-content:space-between;gap:10px}\r\n.dcard .rank{font-family:var(--mono);font-size:9px;color:var(--ink-4);letter-spacing:.08em}\r\n\r\n.dtable{width:100%;border-collapse:collapse;font-size:11.5px}\r\n.dtable th{\r\n  font-family:var(--mono);font-size:8.5px;letter-spacing:.08em;color:var(--ink-4);font-weight:400;\r\n  text-align:left;padding:6px 10px 6px 0;border-bottom:1px solid var(--line-2);white-space:nowrap;\r\n}\r\n.dtable td{padding:7px 10px 7px 0;border-bottom:1px solid var(--line);color:var(--ink-2);vertical-align:top}\r\n.dtable tr:last-child td{border-bottom:0}\r\n.dtable td:first-child{color:var(--ink);white-space:nowrap}\r\n.dtable .num{font-family:var(--mono);text-align:right}\r\n\r\n/* 横向评分条 */\r\n.dbar{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--ink-3)}\r\n.dbar .track{flex:1;height:6px;border-radius:3px;background:var(--paper-3);overflow:hidden;min-width:40px}\r\n.dbar .track i{display:block;height:100%;background:var(--jade);border-radius:3px;transition:width .25s}\r\n.dbar .track i.clay{background:var(--clay)}\r\n.dbar .track i.bad{background:var(--bad)}\r\n.dbar .track i.opt{background:var(--opt)}\r\n.dbar .val{font-family:var(--mono);font-size:10.5px;color:var(--ink-2);min-width:34px;text-align:right}\r\n\r\n/* 图例 */\r\n.dlg{display:flex;flex-wrap:wrap;gap:12px;font-size:10.5px;color:var(--ink-4)}\r\n.dlg span{display:flex;align-items:center;gap:5px}\r\n.dlg i{width:11px;height:3px;border-radius:2px;display:block;flex-shrink:0}\r\n.dlg i.sq{width:9px;height:9px;border-radius:2px}\r\n\r\n/* ---------- 焦点与触控 ---------- */\r\nbutton:focus-visible,input:focus-visible,.tog:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--clay);outline-offset:2px}\r\n.tog{min-height:26px}\r\ninput[type=range]{height:16px}\r\nbutton{touch-action:manipulation}\r\n.dbtn.reset{margin-left:auto}\r\n\r\n/* ---------- 响应式 ---------- */\r\n@media (max-width:900px){\r\n  .dgrid.c2,.dgrid.c2b,.dgrid.c3{grid-template-columns:minmax(0,1fr)}\r\n  .dhead{grid-template-columns:minmax(0,1fr)}\r\n  .dhead-r{justify-content:flex-start}\r\n}\r\n"},{"name":"demo/demo.js","size":57397,"mime":"text/plain","enc":"text","data":"/* =========================================================\r\n   落物打捞工具智能选型 · 可运行示范\r\n   ---------------------------------------------------------\r\n   ① 落物描述结构化（形态 / 外径 / 内径 / 长度 / 井斜 / 落底三态 / 材质 / 卡阻）\r\n   ② 工具知识表：外径、内孔、可捞外径或内径区间、最小咬合长度、\r\n      最大井斜、是否需循环、是否需落底、历史成功率、作业动作\r\n   ③ 两级筛选：硬约束真排除（不进入推荐）→ 加权软评分排序\r\n   ④ 井筒剖面 + 工具构造示意 + 解卡/磨铣工序（不参与打捞评分）\r\n\r\n   物理一致性约定：\r\n   - 外部套入式工具必须满足：可捞上限 dmax < 工具内孔 < 工具外径\r\n   - 公锥 / 捞矛按落物内径判断；母锥 / 卡瓦筒按落物外径判断\r\n   - 所有通过性按套管内通径校核，单边间隙 ≥ 6 mm\r\n   ========================================================= */\r\n(function () {\r\n  'use strict';\r\n\r\n  var FORMS = [\r\n    { key: 'tubular', name: '管状体', desc: '油管 / 钻杆本体', bore: true,  od: 73,  fid: 62, len: 2.4 },\r\n    { key: 'rod',     name: '杆状体', desc: '抽油杆 / 加重杆', bore: false, od: 22,  fid: 0,  len: 2.0 },\r\n    { key: 'cable',   name: '柔索类', desc: '电缆 / 钢丝绳',   bore: false, od: 5,   fid: 0,  len: 3.0 },\r\n    { key: 'solid',   name: '实心小件', desc: '钢球 / 牙轮 / 铁屑', bore: false, od: 12, fid: 0, len: 0.3 },\r\n    { key: 'toolbig', name: '大直径工具', desc: '井下工具 / 扶正器', bore: false, od: 100, fid: 0, len: 1.5 }\r\n  ];\r\n\r\n  /* 套管按「规格 + 通径（drift）」描述；通过性一律用通径，不用套管外径 */\r\n  var CASINGS = [\r\n    { key: '55-17', label: '5-1/2\" 17#', drift: 121.1 },\r\n    { key: '55-23', label: '5-1/2\" 23#', drift: 118.6 },\r\n    { key: '70-29', label: '7\" 29#',     drift: 157.0 }\r\n  ];\r\n\r\n  var CLEARANCE = 6;   /* 工具外径与套管内通径之间必须预留的单边间隙，mm */\r\n\r\n  /* ------------------------------------------------------------------\r\n     工具知识表（11 件打捞工具）\r\n     od      工具外径\r\n     bore    工具内孔（外部套入式工具必须 dmax < bore < od）\r\n     basis   'od' = 按落物外径判断；'id' = 按落物内径判断\r\n     dmin/dmax 可打捞落物外径（或内径）区间\r\n     minLen  最小咬合长度，m；maxLen 工具可容纳的最大落物长度，m\r\n     needBottom 是否必须落底；circ 是否必须循环洗井\r\n     ------------------------------------------------------------------ */\r\n  var TOOLS = [\r\n    { key: 'kawa', name: '卡瓦打捞筒', od: 108, bore: 86, basis: 'od', dmin: 50, dmax: 80,\r\n      sizeLabel: '可捞外径', minLen: 0.3, maxLen: 12, maxIncl: 60, circ: 0, needBottom: 0, succ: 0.88,\r\n      form: { tubular: 1, rod: 0.60, cable: 0.05, solid: 0.05, toolbig: 0.55 },\r\n      op: '下放使鱼顶进入卡瓦筒内孔 0.3 m 以上，上提让卡瓦咬住管壁；先试提确认咬合，再逐步加载，不要用下压代替上提。',\r\n      note: '靠卡瓦咬住管体外壁，适合同心度好的管状落物；外径 108 / 内孔 86 / 可捞 50—80 mm，落物外壁不规则时咬合差。' },\r\n\r\n    { key: 'small', name: '小径卡瓦捞筒', od: 89, bore: 68, basis: 'od', dmin: 32, dmax: 62,\r\n      sizeLabel: '可捞外径', minLen: 0.3, maxLen: 12, maxIncl: 55, circ: 0, needBottom: 0, succ: 0.84,\r\n      form: { tubular: 0.90, rod: 0.70, cable: 0.05, solid: 0.05, toolbig: 0.60 },\r\n      op: '下放套住小直径鱼顶 0.3 m 以上，上提使卡瓦咬合；通径小的套管里优先用它，避免大径工具卡在环空。',\r\n      note: '外径 89 / 内孔 68 / 可捞 32—62 mm；用于小直径油管、杆体和工具接头，通径小的套管里比大径卡瓦筒更容易通过。' },\r\n\r\n    { key: 'box', name: '母锥', od: 95, bore: 88, basis: 'od', dmin: 60, dmax: 84,\r\n      sizeLabel: '可捞外径', minLen: 0.3, maxLen: 12, maxIncl: 50, circ: 0, needBottom: 0, succ: 0.80,\r\n      form: { tubular: 0.80, rod: 0.50, cable: 0.05, solid: 0.05, toolbig: 0.60 },\r\n      op: '下放使落物外壁进入母锥锥孔，缓慢右旋造扣，造扣后上提；造扣期间不要长时间循环。',\r\n      note: '外径 95 / 喇叭口 88 / 可捞外径 60—84 mm；靠落物外壁造扣，适合外壁规则但内孔不通的落物。' },\r\n\r\n    { key: 'pin', name: '公锥', od: 68, bore: null, basis: 'id', dmin: 38, dmax: 62,\r\n      sizeLabel: '可造扣内径', minLen: 0.2, maxLen: 12, maxIncl: 50, circ: 0, needBottom: 0, succ: 0.78,\r\n      form: { tubular: 0.85, rod: 0.45, cable: 0.05, solid: 0.05, toolbig: 0.50 },\r\n      op: '下放使公锥插入落物内孔，加压 5—10 kN 右旋造扣，造扣后上提；落物无内孔时不能用。',\r\n      note: '外径 68 mm；按落物内径 38—62 mm 选型，插入内孔造扣；落物必须有畅通内孔，内径小于 38 mm 或大于 62 mm 都不能用。' },\r\n\r\n    { key: 'spear', name: '捞矛', od: 66, bore: null, basis: 'id', dmin: 40, dmax: 62,\r\n      sizeLabel: '可咬内径', minLen: 0.5, maxLen: 12, maxIncl: 55, circ: 0, needBottom: 0, succ: 0.82,\r\n      form: { tubular: 0.90, rod: 0.50, cable: 0.05, solid: 0.05, toolbig: 0.55 },\r\n      op: '下放使捞矛进入落物内孔，上提让滑块涨开咬住内壁；最小咬合长度 0.5 m，短落物咬不住。',\r\n      note: '外径 66 mm；按落物内径 40—62 mm 选型，滑块涨开咬住内壁；最小咬合长度 0.5 m，短落物不适用。' },\r\n\r\n    { key: 'sucker', name: '抽油杆打捞筒', od: 55, bore: 32, basis: 'od', dmin: 16, dmax: 26,\r\n      sizeLabel: '可捞杆体', minLen: 0.3, maxLen: 12, maxIncl: 60, circ: 0, needBottom: 0, succ: 0.86,\r\n      form: { tubular: 0.20, rod: 1, cable: 0.05, solid: 0.05, toolbig: 0.05 },\r\n      op: '下放套住杆体 0.3 m 以上，上提使卡瓦咬合；遇大接箍先换大规格或单独处理接箍。',\r\n      note: '外径 55 / 内孔 32 / 可捞杆体 16—26 mm（5/8—1 in）；带大接箍的杆串要换大规格或先处理接箍。' },\r\n\r\n    { key: 'basket', name: '篮式捞筒', od: 108, bore: 80, basis: 'od', dmin: 0, dmax: 5,\r\n      sizeLabel: '可捞碎屑', minLen: 0.1, maxLen: 2, maxIncl: 65, circ: 1, needBottom: 0, succ: 0.76,\r\n      form: { tubular: 0.10, rod: 0.20, cable: 0.45, solid: 0.85, toolbig: 0.10 },\r\n      op: '开泵循环，把 0—5 mm 细碎屑随液流带入篮筐；起钻前停泵，避免碎屑回落。',\r\n      note: '外径 108 / 内孔 80 mm；只捞 0—5 mm 细碎屑，靠循环带入，不强制落底；不能循环时基本失效。' },\r\n\r\n    { key: 'magnet', name: '磁力打捞器', od: 60, bore: null, basis: 'od', dmin: 2, dmax: 30,\r\n      sizeLabel: '可吸尺寸', minLen: 0.1, maxLen: 0.6, maxIncl: 75, circ: 0, needBottom: 0, succ: 0.90,\r\n      material: 'ferro', sweet: [5, 30],\r\n      form: { tubular: 0.10, rod: 0.20, cable: 0.05, solid: 1, toolbig: 0.05 },\r\n      op: '下放至鱼顶接触吸附，先活动管柱确认吸附牢靠再起钻；非铁磁性落物和长落物都不适用。',\r\n      note: '外径 60 mm；只对铁磁性材料有效，适合 2—30 mm 的短小件；长落物与堆叠铁屑吸附力不足。' },\r\n\r\n    { key: 'yiba', name: '一把抓', od: 85, bore: 60, basis: 'od', dmin: 5, dmax: 55,\r\n      sizeLabel: '可捞外径', minLen: 0.2, maxLen: 1.2, maxIncl: 45, circ: 0, needBottom: 1, succ: 0.82,\r\n      form: { tubular: 0.25, rod: 0.50, cable: 0.35, solid: 0.90, toolbig: 0.20 },\r\n      op: '下放至鱼顶，继续下放使抓爪收拢抱紧，然后上提；悬空落物会抓空，必须先确认落底。',\r\n      note: '外径 85 / 内孔 60 / 可捞 5—55 mm；靠落底后收爪抓取，落物悬空或井斜大时抓空概率明显上升。' },\r\n\r\n    { key: 'rope', name: '绳类打捞钩', od: 50, bore: null, basis: 'od', dmin: 3, dmax: 45,\r\n      sizeLabel: '可钩挂尺寸', minLen: 0.3, maxLen: 50, maxIncl: 70, circ: 0, needBottom: 0, succ: 0.84,\r\n      form: { tubular: 0.10, rod: 0.35, cable: 1, solid: 0.10, toolbig: 0.05 },\r\n      op: '下放过鱼顶后上提，使钩子钩挂缠绕电缆或钢丝绳；大斜度井电缆贴壁，需要多次活动管柱。',\r\n      note: '外径 50 mm；专捞电缆、钢丝绳，靠钩挂缠绕；井斜大时电缆贴壁，需要多次活动管柱。' },\r\n\r\n    { key: 'thin', name: '细钢丝捞钩', od: 36, bore: null, basis: 'od', dmin: 1, dmax: 12,\r\n      sizeLabel: '可钩挂尺寸', minLen: 0.1, maxLen: 50, maxIncl: 55, circ: 0, needBottom: 0, succ: 0.74,\r\n      form: { tubular: 0.10, rod: 0.30, cable: 0.90, solid: 0.10, toolbig: 0.05 },\r\n      op: '缓慢下放，钩住细钢丝后轻提，避免拉断；可配合反循环把细钢丝带出。',\r\n      note: '外径 36 mm；专捞细钢丝、测井电缆和仪器引线，钩尖细、拉力小，遇卡不要硬提。' }\r\n  ];\r\n\r\n  /* 工序工具：不参与打捞排序，只按卡阻状态推荐 */\r\n  var PREP = [\r\n    { key: 'wash', name: '套铣筒', od: 108, circ: 1, when: '砂卡 / 水泥卡 / 落物被埋',\r\n      note: '套住落物与套管环空，循环洗出砂桥或水泥环；套铣到位后再下打捞工具。' },\r\n    { key: 'mill', name: '平底磨鞋', od: 105, circ: 1, when: '鱼顶不规则 / 大件无法直接捞 / 落物被埋',\r\n      note: '加压磨铣鱼顶或大件，磨屑随循环带出；磨铣后必须清屑。' },\r\n    { key: 'basket', name: '篮式捞筒 / 反循环', od: 108, circ: 1, when: '磨铣后清屑',\r\n      note: '清除磨铣产生的铁屑，避免二次落物；也可用反循环打捞篮。' }\r\n  ];\r\n\r\n  var W = { form: 0.32, size: 0.26, incl: 0.16, succ: 0.16, cond: 0.10 };\r\n\r\n  var DEFAULTS = {\r\n    form: 'tubular', casing: 0, od: 73, fishId: 62, len: 2.4, incl: 18,\r\n    bottom: null, circ: true, material: 'ferro', stuck: 'none'\r\n  };\r\n\r\n  var state = clone(DEFAULTS);\r\n\r\n  /* ---------- 小工具 ---------- */\r\n  function clone(o) {\r\n    var r = {}, k;\r\n    for (k in o) { if (Object.prototype.hasOwnProperty.call(o, k)) r[k] = o[k]; }\r\n    return r;\r\n  }\r\n  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }\r\n  function fmt1(v) { return (Math.round(v * 10) / 10).toFixed(1); }\r\n  function el(id) { return document.getElementById(id); }\r\n  function curCasing() { return CASINGS[state.casing]; }\r\n  function FORM_OF(k) {\r\n    var i;\r\n    for (i = 0; i < FORMS.length; i++) if (FORMS[i].key === k) return FORMS[i];\r\n    return FORMS[0];\r\n  }\r\n  function formNames(t) {\r\n    if (t.basis === 'id') return '管状体（需内孔）';\r\n    var a = [];\r\n    FORMS.forEach(function (f) { if ((t.form[f.key] || 0) >= 0.4) a.push(f.name); });\r\n    return a.length ? a.join('、') : '—';\r\n  }\r\n  function fishValue(t, s) { return t.basis === 'id' ? s.fishId : s.od; }\r\n\r\n  /* ---------- 尺寸评分：落在区间中段得满分，贴近边界缓降 ---------- */\r\n  function sizeScore(t, s) {\r\n    var v = fishValue(t, s);\r\n    if (t.sweet && v >= t.sweet[0] && v <= t.sweet[1]) return 1;\r\n    var span = t.dmax - t.dmin;\r\n    if (span <= 0) return 1;\r\n    var pos = (v - t.dmin) / span;\r\n    var edge = Math.min(pos, 1 - pos);\r\n    return 0.65 + 0.35 * Math.min(1, edge / 0.3);\r\n  }\r\n\r\n  /* ---------- 硬约束 + 软评分 ---------- */\r\n  function evaluate(t, s) {\r\n    var reasons = [];\r\n    var warns = [];\r\n    var limit = s.drift - 2 * CLEARANCE;\r\n\r\n    if (t.od > limit) {\r\n      reasons.push('工具外径 ' + t.od + ' mm > 通径 ' + fmt1(s.drift) + ' − 2×6 = ' + fmt1(limit) + ' mm');\r\n    }\r\n    if (s.stuck === 'buried') {\r\n      reasons.push('落物被埋，鱼顶不可达，需先套铣 / 磨铣清障');\r\n    }\r\n\r\n    if (t.basis === 'id') {\r\n      if (!s.fishBore) {\r\n        reasons.push('落物无内孔，' + t.name + '无法插入造扣');\r\n      } else if (!s.fishId) {\r\n        reasons.push('未给出落物内径，无法校核' + t.name);\r\n      } else if (s.fishId < t.dmin || s.fishId > t.dmax) {\r\n        reasons.push('落物内径 ' + s.fishId + ' mm 超出' + t.sizeLabel + ' ' + t.dmin + '—' + t.dmax + ' mm');\r\n      }\r\n    } else {\r\n      if (s.od < t.dmin || s.od > t.dmax) {\r\n        reasons.push('落物外径 ' + s.od + ' mm 超出' + t.sizeLabel + ' ' + t.dmin + '—' + t.dmax + ' mm');\r\n      }\r\n    }\r\n\r\n    if (t.material === 'ferro' && s.material !== 'ferro') {\r\n      reasons.push('落物为非铁磁性，磁力打捞器无效');\r\n    }\r\n    if (s.incl > t.maxIncl) {\r\n      reasons.push('井斜 ' + s.incl + '° > 工具允许 ' + t.maxIncl + '°');\r\n    }\r\n    if (t.circ && !s.circ) {\r\n      reasons.push('工具需循环洗井，本井不可循环');\r\n    }\r\n    if (t.needBottom && s.bottom === false) {\r\n      reasons.push('工具需落底，落物悬空');\r\n    }\r\n    if (s.len < t.minLen) {\r\n      reasons.push('落物长度 ' + fmt1(s.len) + ' m < 最小咬合长度 ' + fmt1(t.minLen) + ' m');\r\n    }\r\n    if (s.len > t.maxLen) {\r\n      reasons.push('落物长度 ' + fmt1(s.len) + ' m > 工具可容纳 ' + fmt1(t.maxLen) + ' m');\r\n    }\r\n\r\n    if (reasons.length) return { out: true, reasons: reasons, why: reasons.join('；') };\r\n\r\n    if (t.needBottom && s.bottom === null) {\r\n      warns.push('需落底：状态未知（落底分支可用，悬空分支不可用）');\r\n    }\r\n    if (s.stuck === 'sand') warns.push('砂卡：工具串建议加震击器 + 安全接头');\r\n    if (s.stuck === 'cement') warns.push('水泥卡：工具串建议加震击器 + 安全接头');\r\n\r\n    var formScore = t.form[s.form] || 0;\r\n    var size = sizeScore(t, s);\r\n\r\n    var inclScore = 1;\r\n    if (s.incl > t.maxIncl - 10) {\r\n      inclScore = 1 - (s.incl - (t.maxIncl - 10)) / 10 * 0.35;\r\n    }\r\n    inclScore = Math.max(0.65, Math.min(1, inclScore));\r\n\r\n    var condScore = 1;\r\n    if (t.needBottom && s.bottom === null) condScore -= 0.30;\r\n    if (s.stuck === 'sand' || s.stuck === 'cement') condScore -= 0.06;\r\n    condScore = Math.max(0, condScore);\r\n\r\n    var parts = [\r\n      { k: '形态匹配', p: formScore, w: W.form },\r\n      { k: '尺寸隶属', p: size, w: W.size },\r\n      { k: '井斜适应', p: inclScore, w: W.incl },\r\n      { k: '历史成功率', p: t.succ, w: W.succ },\r\n      { k: '工况条件', p: condScore, w: W.cond }\r\n    ];\r\n    var score = parts.reduce(function (a, x) { return a + x.w * x.p; }, 0);\r\n    return { out: false, score: score, parts: parts, warns: warns };\r\n  }\r\n\r\n  function rank(s) {\r\n    return TOOLS.map(function (t) {\r\n      var e = evaluate(t, s);\r\n      return { t: t, e: e, score: e.out ? -1 : e.score };\r\n    }).sort(function (a, b) { return b.score - a.score; });\r\n  }\r\n  function bestOf(rows) {\r\n    var i;\r\n    for (i = 0; i < rows.length; i++) if (!rows[i].e.out) return rows[i];\r\n    return null;\r\n  }\r\n\r\n  /* ---------- 起下钻：只给整数 / 区间 ---------- */\r\n  function tripText(best) {\r\n    if (!best) return '—';\r\n    if (best.score >= 0.80) return '1 趟（预计）';\r\n    if (best.score >= 0.62) return '1—2 趟';\r\n    return '2—3 趟';\r\n  }\r\n\r\n  function sizeMeta(t) {\r\n    var head = '外径 ' + t.od + ' mm · ';\r\n    if (t.bore) head += '内孔 ' + t.bore + ' mm · ';\r\n    else if (t.basis === 'id') head += '无内孔工具（插入落物内孔）· ';\r\n    else head += '无内孔 · ';\r\n    return head + t.sizeLabel + ' ' + t.dmin + '—' + t.dmax + ' mm · 咬合 ≥' + t.minLen + ' m';\r\n  }\r\n\r\n  function toolTitle(t) {\r\n    return t.name + '｜' + sizeMeta(t) +\r\n      '｜需落底 ' + (t.needBottom ? '是' : '否') +\r\n      '｜需循环 ' + (t.circ ? '是' : '否') +\r\n      '｜最大井斜 ' + t.maxIncl + '°' +\r\n      '｜历史成功率 ' + Math.round(t.succ * 100) + '%' +\r\n      '｜' + t.note;\r\n  }\r\n\r\n  /* =========================================================\r\n     工具构造示意（分工具画，标签不裁切）\r\n     ========================================================= */\r\n  function toolArt(key) {\r\n    var S = '#1d4e50', F = '#e7eee9', R = '#a64b3c';\r\n    var g = '<g transform=\"translate(105,8) scale(1.04)\">';\r\n\r\n    function sub(w) {\r\n      return '<rect x=\"' + (-w / 2) + '\" y=\"0\" width=\"' + w + '\" height=\"14\" rx=\"3\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n    }\r\n    function lbl(txt) {\r\n      return '<text x=\"0\" y=\"148\" font-size=\"9\" fill=\"#6f7a7c\" text-anchor=\"middle\">' + txt + '<\/text>';\r\n    }\r\n\r\n    if (key === 'kawa' || key === 'small' || key === 'sucker') {\r\n      var bw = key === 'kawa' ? 62 : (key === 'small' ? 48 : 34);\r\n      var bh = key === 'kawa' ? 76 : (key === 'small' ? 70 : 80);\r\n      var mw = key === 'kawa' ? 44 : (key === 'small' ? 32 : 20);\r\n      var mh = key === 'kawa' ? 36 : (key === 'small' ? 34 : 44);\r\n      g += sub(bw * 0.58);\r\n      g += '<rect x=\"' + (-bw / 2) + '\" y=\"14\" width=\"' + bw + '\" height=\"' + bh + '\" rx=\"3\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<rect x=\"' + (-mw / 2) + '\" y=\"' + (bh - mh + 14) + '\" width=\"' + mw + '\" height=\"' + mh + '\" fill=\"#ffffff\" stroke=\"' + S + '\" stroke-dasharray=\"3 2\"/>';\r\n      g += '<path d=\"M' + (-bw / 2) + ' ' + (bh - mh + 22) + ' L' + (-bw / 2 + 14) + ' ' + (bh - mh + 30) + ' L' + (-bw / 2) + ' ' + (bh - mh + 38) + ' Z\" fill=\"' + S + '\" opacity=\".75\"/>';\r\n      g += '<path d=\"M' + (bw / 2) + ' ' + (bh - mh + 22) + ' L' + (bw / 2 - 14) + ' ' + (bh - mh + 30) + ' L' + (bw / 2) + ' ' + (bh - mh + 38) + ' Z\" fill=\"' + S + '\" opacity=\".75\"/>';\r\n      if (key === 'sucker') g += '<line x1=\"-8\" y1=\"18\" x2=\"-8\" y2=\"' + (bh + 10) + '\" stroke=\"' + S + '\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/>';\r\n      g += lbl(key === 'kawa' ? '卡瓦打捞筒 · 咬管体外壁' : (key === 'small' ? '小径卡瓦捞筒 · 32—62' : '抽油杆筒 · 杆体 16—26'));\r\n    } else if (key === 'box') {\r\n      g += sub(44);\r\n      g += '<rect x=\"-26\" y=\"14\" width=\"52\" height=\"28\" rx=\"3\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<path d=\"M-26 42 L26 42 L40 92 L-40 92 Z\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<path d=\"M-14 48 L14 48 L26 86 L-26 86 Z\" fill=\"none\" stroke=\"' + S + '\" stroke-dasharray=\"3 2\"/>';\r\n      g += '<line x1=\"-24\" y1=\"62\" x2=\"24\" y2=\"62\" stroke=\"' + S + '\" stroke-width=\"1\" opacity=\".45\"/>';\r\n      g += '<line x1=\"-28\" y1=\"76\" x2=\"28\" y2=\"76\" stroke=\"' + S + '\" stroke-width=\"1\" opacity=\".45\"/>';\r\n      g += lbl('母锥 · 落物外壁造扣');\r\n    } else if (key === 'pin') {\r\n      g += sub(30);\r\n      g += '<rect x=\"-18\" y=\"14\" width=\"36\" height=\"20\" rx=\"3\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<path d=\"M-18 34 L18 34 L10 96 L-10 96 Z\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      for (var i = 0; i < 5; i++) {\r\n        var yy = 42 + i * 10;\r\n        var hw = 16 - i * 1.4;\r\n        g += '<line x1=\"' + (-hw) + '\" y1=\"' + yy + '\" x2=\"' + hw + '\" y2=\"' + yy + '\" stroke=\"' + S + '\" stroke-width=\"1\" opacity=\".55\"/>';\r\n      }\r\n      g += lbl('公锥 · 插入内孔造扣');\r\n    } else if (key === 'spear') {\r\n      g += sub(24);\r\n      g += '<rect x=\"-7\" y=\"14\" width=\"14\" height=\"72\" rx=\"2\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<path d=\"M-7 38 L-22 50 L-22 82 L-7 68 Z\" fill=\"' + S + '\" opacity=\".55\"/>';\r\n      g += '<path d=\"M7 38 L22 50 L22 82 L7 68 Z\" fill=\"' + S + '\" opacity=\".55\"/>';\r\n      g += '<line x1=\"-22\" y1=\"54\" x2=\"-8\" y2=\"44\" stroke=\"#fff\" stroke-width=\"1\" opacity=\".7\"/>';\r\n      g += '<line x1=\"22\" y1=\"54\" x2=\"8\" y2=\"44\" stroke=\"#fff\" stroke-width=\"1\" opacity=\".7\"/>';\r\n      g += lbl('捞矛 · 滑块咬内壁');\r\n    } else if (key === 'basket') {\r\n      g += sub(34);\r\n      g += '<rect x=\"-30\" y=\"14\" width=\"60\" height=\"38\" rx=\"3\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<rect x=\"-24\" y=\"52\" width=\"48\" height=\"42\" rx=\"2\" fill=\"#ffffff\" stroke=\"' + S + '\" stroke-dasharray=\"3 2\"/>';\r\n      for (var j = 0; j < 6; j++) {\r\n        g += '<circle cx=\"' + (-10 + (j % 3) * 10) + '\" cy=\"' + (62 + Math.floor(j / 3) * 12) + '\" r=\"1.5\" fill=\"' + S + '\" opacity=\".5\"/>';\r\n      }\r\n      g += lbl('篮式捞筒 · 循环带入');\r\n    } else if (key === 'magnet') {\r\n      g += sub(30);\r\n      g += '<rect x=\"-20\" y=\"14\" width=\"40\" height=\"64\" rx=\"3\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<rect x=\"-20\" y=\"78\" width=\"40\" height=\"10\" fill=\"' + R + '\" stroke=\"' + R + '\"/>';\r\n      g += '<text x=\"-10\" y=\"86\" font-size=\"7\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"monospace\">S<\/text>';\r\n      g += '<text x=\"10\" y=\"86\" font-size=\"7\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"monospace\">N<\/text>';\r\n      g += '<path d=\"M-8 90 C-18 102 -12 110 0 112 M8 90 C18 102 12 110 0 112\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1\" stroke-dasharray=\"3 3\" opacity=\".6\"/>';\r\n      g += lbl('磁力打捞器 · 接触吸附');\r\n    } else if (key === 'yiba') {\r\n      g += sub(30);\r\n      g += '<rect x=\"-22\" y=\"14\" width=\"44\" height=\"46\" rx=\"3\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<path d=\"M-18 60 C-22 88 -10 104 0 106 C10 104 22 88 18 60\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"2\"/>';\r\n      g += '<path d=\"M-9 60 C-11 82 -4 94 0 96 M9 60 C11 82 4 94 0 96\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1.2\" opacity=\".65\"/>';\r\n      g += lbl('一把抓 · 下放收爪');\r\n    } else if (key === 'rope') {\r\n      g += sub(20);\r\n      g += '<rect x=\"-8\" y=\"14\" width=\"16\" height=\"48\" rx=\"2\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<path d=\"M0 62 C0 88 -24 88 -24 72 C-24 62 -14 58 -6 64\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"2.2\"/>';\r\n      g += '<path d=\"M-22 72 L-30 68 M-18 82 L-26 86\" stroke=\"' + S + '\" stroke-width=\"1.4\"/>';\r\n      g += lbl('绳类打捞钩 · 钩挂缠绕');\r\n    } else if (key === 'thin') {\r\n      g += sub(14);\r\n      g += '<rect x=\"-4\" y=\"14\" width=\"8\" height=\"50\" rx=\"2\" fill=\"' + F + '\" stroke=\"' + S + '\"/>';\r\n      g += '<path d=\"M0 64 C0 86 -18 86 -18 72 C-18 64 -10 61 -4 66\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1.2\"/>';\r\n      g += '<path d=\"M-16 72 L-22 69\" stroke=\"' + S + '\" stroke-width=\"1\"/>';\r\n      g += lbl('细钢丝捞钩 · 钩出细钢丝');\r\n    }\r\n    return g + '<\/g>';\r\n  }\r\n\r\n  /* =========================================================\r\n     井筒剖面：通径按毫米比例绘制，落底贴井底，工具与落物咬合\r\n     ========================================================= */\r\n  function drawSchematic(best) {\r\n    var c = curCasing();\r\n    var PX = 0.66;                 /* mm → px */\r\n    var CX = 144, TOP = 62, BOT = 392, CY = 50;\r\n    var vis = state.incl * 0.45;   /* 图示倾角按 0.45 缩小，标注非等比例 */\r\n    var a = vis * Math.PI / 180;\r\n    var half = c.drift * PX / 2;\r\n    var wall = 6;\r\n    var fishW = Math.max(5, state.od * PX);\r\n    var fishH = Math.max(8, Math.min(120, state.len * 10));\r\n    var fishTop = state.bottom === false ? 188 : BOT - fishH;\r\n    var fishBottom = fishTop + fishH;\r\n    var dashed = state.bottom === null;\r\n\r\n    var toolTop = 0, toolBottom = 0, toolW = 0;\r\n    if (best) {\r\n      toolW = best.t.od * PX;\r\n      var overlap = best.t.key === 'magnet' ? 2 :\r\n        ((best.t.key === 'rope' || best.t.key === 'thin') ? 8 : 18);\r\n      if (state.bottom === true) toolBottom = Math.min(BOT - 4, fishTop + overlap);\r\n      else if (state.bottom === false) toolBottom = fishTop - 10;\r\n      else toolBottom = Math.min(BOT - 4, fishTop + overlap);  /* 未知道：按落底分支画咬合，鱼顶用虚线标未知 */\r\n      toolTop = Math.max(TOP + 20, toolBottom - 64);\r\n    }\r\n\r\n    function rp(x, y) {\r\n      var dx = x - CX, dy = y - CY;\r\n      return {\r\n        x: CX + dx * Math.cos(a) - dy * Math.sin(a) + shiftX,\r\n        y: CY + dx * Math.sin(a) + dy * Math.cos(a)\r\n      };\r\n    }\r\n\r\n    /* 大斜度时井底会转到 viewBox 左侧之外：整体右移，保证套管与标签不出框 */\r\n    var sinA = Math.sin(a), cosA = Math.cos(a);\r\n    var xLeftBottom = CX - (half + wall) * cosA - (BOT - CY) * sinA;\r\n    var shiftX = Math.max(0, 8 - xLeftBottom);\r\n\r\n    var s = '<g transform=\"translate(' + shiftX.toFixed(1) + ',0) rotate(' + vis.toFixed(2) + ',' + CX + ',' + CY + ')\">';\r\n\r\n    /* 套管壁（内径 = 通径） */\r\n    s += '<rect x=\"' + (CX - half - wall) + '\" y=\"' + TOP + '\" width=\"' + wall + '\" height=\"' + (BOT - TOP) + '\" fill=\"#f0ede4\" stroke=\"#d3c9b6\"/>';\r\n    s += '<rect x=\"' + (CX + half) + '\" y=\"' + TOP + '\" width=\"' + wall + '\" height=\"' + (BOT - TOP) + '\" fill=\"#f0ede4\" stroke=\"#d3c9b6\"/>';\r\n    /* 井口 */\r\n    s += '<rect x=\"' + (CX - half - wall - 8) + '\" y=\"' + (TOP - 12) + '\" width=\"' + (2 * (half + wall) + 16) + '\" height=\"12\" rx=\"3\" fill=\"#e3dccd\" stroke=\"#d3c9b6\"/>';\r\n    /* 井底 */\r\n    s += '<rect x=\"' + (CX - half) + '\" y=\"' + BOT + '\" width=\"' + (2 * half) + '\" height=\"6\" fill=\"#e3dccd\" stroke=\"#d3c9b6\"/>';\r\n\r\n    /* 落物 */\r\n    s += '<rect x=\"' + (CX - fishW / 2) + '\" y=\"' + fishTop + '\" width=\"' + fishW + '\" height=\"' + fishH + '\" rx=\"2\" fill=\"#f5e6e1\" stroke=\"#a64b3c\" stroke-width=\"1.4\"' + (dashed ? ' stroke-dasharray=\"4 3\"' : '') + '/>';\r\n    if (state.form === 'cable') {\r\n      s += '<path d=\"M' + (CX - fishW / 2 + 2) + ' ' + (fishTop + 4) + ' q' + (fishW / 2) + ' 6 0 12 q' + (-fishW / 2) + ' 6 0 12\" fill=\"none\" stroke=\"#a64b3c\" stroke-width=\"1\" opacity=\".7\"/>';\r\n    }\r\n\r\n    /* 工具与工具串 */\r\n    if (best) s += toolGlyph(best.t, toolTop, toolBottom, toolW);\r\n\r\n    s += '<\/g>';\r\n\r\n    /* ---- 文字标签（放在套管外侧，避免压住套管壁） ---- */\r\n    var pFish = rp(CX + half + wall + 6, fishTop + 10);\r\n    var fishAnchor = 'start';\r\n    s += '<text x=\"' + pFish.x.toFixed(1) + '\" y=\"' + pFish.y.toFixed(1) + '\" font-size=\"9\" fill=\"#a64b3c\" text-anchor=\"' + fishAnchor + '\">落物 ' + state.od + ' mm<\/text>';\r\n    s += '<text x=\"' + pFish.x.toFixed(1) + '\" y=\"' + (pFish.y + 12).toFixed(1) + '\" font-size=\"8.5\" fill=\"#a64b3c\" text-anchor=\"' + fishAnchor + '\">' + fmt1(state.len) + ' m · ' + (state.bottom === true ? '已落底' : (state.bottom === false ? '悬空' : '落底未知')) + '<\/text>';\r\n\r\n    var pWell = rp(CX + half + wall + 8, TOP + 2);\r\n    s += '<text x=\"' + pWell.x.toFixed(1) + '\" y=\"' + pWell.y.toFixed(1) + '\" font-size=\"8.5\" fill=\"#99a3a4\" font-family=\"monospace\">井口<\/text>';\r\n\r\n    var pBot = rp(CX, BOT + 18);\r\n    s += '<text x=\"' + pBot.x.toFixed(1) + '\" y=\"' + pBot.y.toFixed(1) + '\" font-size=\"8.5\" fill=\"#99a3a4\" text-anchor=\"middle\">井底<\/text>';\r\n\r\n    if (state.bottom === false) {\r\n      var pSus = rp(CX, fishBottom + 14);\r\n      s += '<path d=\"M' + rp(CX - half, fishBottom).x.toFixed(1) + ' ' + rp(CX - half, fishBottom).y.toFixed(1) + ' L' + rp(CX + half, fishBottom).x.toFixed(1) + ' ' + rp(CX + half, fishBottom).y.toFixed(1) + '\" stroke=\"#e3dccd\" stroke-dasharray=\"4 3\"/>';\r\n      s += '<text x=\"' + pSus.x.toFixed(1) + '\" y=\"' + pSus.y.toFixed(1) + '\" font-size=\"8.5\" fill=\"#99a3a4\" text-anchor=\"middle\">悬空（未落底）<\/text>';\r\n    }\r\n    if (state.bottom === null) {\r\n      var pUnk = rp(CX + half + wall + 6, BOT + 20);\r\n      s += '<text x=\"' + pUnk.x.toFixed(1) + '\" y=\"' + pUnk.y.toFixed(1) + '\" font-size=\"8.5\" fill=\"#9a6b1d\" text-anchor=\"start\">虚线示落底位置<\/text>';\r\n    }\r\n\r\n    if (best) {\r\n      var pR = rp(Math.max(CX + toolW / 2 + 8, CX + half + wall + 4), toolTop + 9);\r\n      var pL = rp(Math.min(CX - toolW / 2 - 8, CX - half - wall - 4), toolTop + 9);\r\n      var useR = pR.x < 330;\r\n      var pT = useR ? pR : pL;\r\n      s += '<text x=\"' + pT.x.toFixed(1) + '\" y=\"' + pT.y.toFixed(1) + '\" font-size=\"9\" fill=\"#1d4e50\" text-anchor=\"' + (useR ? 'start' : 'end') + '\">' + best.t.name + '<\/text>';\r\n      if (state.bottom === true) {\r\n        var contact = best.t.key === 'magnet' ? '已接触' :\r\n          (best.t.key === 'pin' || best.t.key === 'box' ? '已造扣' :\r\n            (best.t.key === 'yiba' ? '已收爪' :\r\n              (best.t.key === 'rope' || best.t.key === 'thin' ? '已钩挂' :\r\n                (best.t.key === 'basket' ? '循环带入' : '已咬合'))));\r\n        s += '<text x=\"' + pT.x.toFixed(1) + '\" y=\"' + (pT.y + 11).toFixed(1) + '\" font-size=\"8\" fill=\"#6f7a7c\" text-anchor=\"' + (useR ? 'start' : 'end') + '\">' + contact + '<\/text>';\r\n      } else if (state.bottom === null) {\r\n        s += '<text x=\"' + pT.x.toFixed(1) + '\" y=\"' + (pT.y + 11).toFixed(1) + '\" font-size=\"8\" fill=\"#9a6b1d\" text-anchor=\"' + (useR ? 'start' : 'end') + '\">待铅印确认<\/text>';\r\n      }\r\n    }\r\n\r\n    /* ---- 井斜角标：从垂直方向量起，与井身使用同一图示角度 ---- */\r\n    s += '<g transform=\"translate(10,26)\">';\r\n    s += '<line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"28\" stroke=\"#beb19a\" stroke-dasharray=\"3 2\"/>';\r\n    s += '<line x1=\"0\" y1=\"0\" x2=\"' + (-28 * Math.sin(a)).toFixed(1) + '\" y2=\"' + (28 * Math.cos(a)).toFixed(1) + '\" stroke=\"#1d4e50\" stroke-width=\"1.6\"/>';\r\n    if (vis > 1) {\r\n      s += '<path d=\"M0 14 A14 14 0 0 0 ' + (-14 * Math.sin(a)).toFixed(1) + ' ' + (14 * Math.cos(a)).toFixed(1) + '\" fill=\"none\" stroke=\"#1d4e50\" stroke-width=\"1\" opacity=\".55\"/>';\r\n    }\r\n    s += '<text x=\"0\" y=\"42\" font-size=\"9\" fill=\"#4a585c\" font-family=\"monospace\">井斜 ' + state.incl + '°<\/text>';\r\n    s += '<text x=\"0\" y=\"53\" font-size=\"7.5\" fill=\"#99a3a4\" font-family=\"monospace\">图示 ' + vis.toFixed(1) + '°<\/text>';\r\n    s += '<text x=\"0\" y=\"63\" font-size=\"7.5\" fill=\"#99a3a4\" font-family=\"monospace\">非等比例<\/text>';\r\n    s += '<\/g>';\r\n\r\n    s += '<text x=\"370\" y=\"16\" font-size=\"7.5\" fill=\"#beb19a\" text-anchor=\"end\" font-family=\"monospace\">示意 · 非等比例<\/text>';\r\n\r\n    el('schematic').innerHTML = s;\r\n  }\r\n\r\n  function toolGlyph(t, top, bot, w) {\r\n    var cx = 144, h = bot - top, BOT = 392, S = '#1d4e50', s = '';\r\n    s += '<line x1=\"' + cx + '\" y1=\"62\" x2=\"' + cx + '\" y2=\"' + top + '\" stroke=\"#cbd6d2\" stroke-width=\"3\"/>';\r\n\r\n    if (t.key === 'kawa' || t.key === 'small' || t.key === 'sucker' || t.key === 'basket') {\r\n      s += '<rect x=\"' + (cx - w / 2) + '\" y=\"' + top + '\" width=\"' + w + '\" height=\"' + h + '\" rx=\"2\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\" stroke-width=\"1.2\"/>';\r\n      s += '<rect x=\"' + (cx - w / 2 + 4) + '\" y=\"' + (bot - 20) + '\" width=\"' + (w - 8) + '\" height=\"20\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>';\r\n      s += '<path d=\"M' + (cx - w / 2 + 3) + ' ' + (bot - 16) + ' L' + (cx - w / 2 + 13) + ' ' + (bot - 11) + ' L' + (cx - w / 2 + 3) + ' ' + (bot - 6) + ' Z\" fill=\"' + S + '\" opacity=\".8\"/>';\r\n      s += '<path d=\"M' + (cx + w / 2 - 3) + ' ' + (bot - 16) + ' L' + (cx + w / 2 - 13) + ' ' + (bot - 11) + ' L' + (cx + w / 2 - 3) + ' ' + (bot - 6) + ' Z\" fill=\"' + S + '\" opacity=\".8\"/>';\r\n      if (t.key === 'basket') {\r\n        for (var i = 0; i < 6; i++) {\r\n          s += '<circle cx=\"' + (cx - 10 + (i % 3) * 10) + '\" cy=\"' + (bot - 16 + Math.floor(i / 3) * 7) + '\" r=\"1.2\" fill=\"' + S + '\" opacity=\".5\"/>';\r\n        }\r\n      }\r\n    } else if (t.key === 'box') {\r\n      var tw = w * 0.55;\r\n      s += '<path d=\"M' + (cx - tw / 2) + ' ' + top + ' L' + (cx + tw / 2) + ' ' + top + ' L' + (cx + w / 2) + ' ' + bot + ' L' + (cx - w / 2) + ' ' + bot + ' Z\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\" stroke-width=\"1.2\"/>';\r\n      s += '<path d=\"M' + (cx - tw / 2 + 4) + ' ' + (top + 4) + ' L' + (cx + tw / 2 - 4) + ' ' + (top + 4) + ' L' + (cx + w / 2 - 6) + ' ' + (bot - 3) + ' L' + (cx - w / 2 + 6) + ' ' + (bot - 3) + ' Z\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>';\r\n      s += '<line x1=\"' + (cx - w / 2 + 7) + '\" y1=\"' + (bot - 12) + '\" x2=\"' + (cx + w / 2 - 7) + '\" y2=\"' + (bot - 12) + '\" stroke=\"' + S + '\" opacity=\".4\"/>';\r\n    } else if (t.key === 'pin') {\r\n      s += '<rect x=\"' + (cx - 9) + '\" y=\"' + top + '\" width=\"18\" height=\"18\" rx=\"2\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\"/>';\r\n      s += '<path d=\"M' + (cx - 9) + ' ' + (top + 18) + ' L' + (cx + 9) + ' ' + (top + 18) + ' L' + (cx + 5) + ' ' + bot + ' L' + (cx - 5) + ' ' + bot + ' Z\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\"/>';\r\n      for (var j = 0; j < 4; j++) {\r\n        var yy = top + 24 + j * ((bot - top - 24) / 4);\r\n        s += '<line x1=\"' + (cx - 8 + j * 0.9) + '\" y1=\"' + yy + '\" x2=\"' + (cx + 8 - j * 0.9) + '\" y2=\"' + yy + '\" stroke=\"' + S + '\" stroke-width=\".8\" opacity=\".55\"/>';\r\n      }\r\n    } else if (t.key === 'spear') {\r\n      s += '<rect x=\"' + (cx - 5) + '\" y=\"' + top + '\" width=\"10\" height=\"' + (h - 6) + '\" rx=\"2\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\"/>';\r\n      s += '<path d=\"M' + (cx - 5) + ' ' + (top + 22) + ' L' + (cx - 18) + ' ' + (top + 34) + ' L' + (cx - 18) + ' ' + (bot - 4) + ' L' + (cx - 5) + ' ' + (bot - 16) + ' Z\" fill=\"' + S + '\" opacity=\".55\"/>';\r\n      s += '<path d=\"M' + (cx + 5) + ' ' + (top + 22) + ' L' + (cx + 18) + ' ' + (top + 34) + ' L' + (cx + 18) + ' ' + (bot - 4) + ' L' + (cx + 5) + ' ' + (bot - 16) + ' Z\" fill=\"' + S + '\" opacity=\".55\"/>';\r\n    } else if (t.key === 'magnet') {\r\n      s += '<rect x=\"' + (cx - w / 2) + '\" y=\"' + top + '\" width=\"' + w + '\" height=\"' + h + '\" rx=\"3\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\"/>';\r\n      s += '<rect x=\"' + (cx - w / 2) + '\" y=\"' + (bot - 9) + '\" width=\"' + w + '\" height=\"9\" fill=\"#a64b3c\"/>';\r\n      s += '<text x=\"' + cx + '\" y=\"' + (bot - 2) + '\" font-size=\"6\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"monospace\">S<\/text>';\r\n      if (bot < BOT - 24) {\r\n        s += '<path d=\"M' + (cx - 8) + ' ' + (bot + 2) + ' C' + (cx - 16) + ' ' + (bot + 12) + ' ' + (cx - 8) + ' ' + (bot + 18) + ' ' + cx + ' ' + (bot + 18) + ' M' + (cx + 8) + ' ' + (bot + 2) + ' C' + (cx + 16) + ' ' + (bot + 12) + ' ' + (cx + 8) + ' ' + (bot + 18) + ' ' + cx + ' ' + (bot + 18) + '\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1\" stroke-dasharray=\"2 2\" opacity=\".6\"/>';\r\n      }\r\n    } else if (t.key === 'yiba') {\r\n      s += '<rect x=\"' + (cx - w / 2) + '\" y=\"' + top + '\" width=\"' + w + '\" height=\"' + (h - 10) + '\" rx=\"2\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\"/>';\r\n      s += '<path d=\"M' + (cx - w / 2 + 4) + ' ' + (bot - 18) + ' C' + (cx - w / 2 - 2) + ' ' + (bot + 10) + ' ' + (cx - 6) + ' ' + (bot + 14) + ' ' + cx + ' ' + (bot + 12) + '\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1.6\"/>';\r\n      s += '<path d=\"M' + (cx + w / 2 - 4) + ' ' + (bot - 18) + ' C' + (cx + w / 2 + 2) + ' ' + (bot + 10) + ' ' + (cx + 6) + ' ' + (bot + 14) + ' ' + cx + ' ' + (bot + 12) + '\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"1.6\"/>';\r\n    } else {\r\n      var bw = t.key === 'thin' ? 5 : 10;\r\n      s += '<rect x=\"' + (cx - bw / 2) + '\" y=\"' + top + '\" width=\"' + bw + '\" height=\"' + (h - 8) + '\" rx=\"2\" fill=\"rgba(29,78,80,.12)\" stroke=\"' + S + '\"/>';\r\n      s += '<path d=\"M' + cx + ' ' + (bot - 8) + ' C' + cx + ' ' + (bot + 10) + ' ' + (cx - 14) + ' ' + (bot + 8) + ' ' + (cx - 14) + ' ' + (bot - 2) + ' C' + (cx - 14) + ' ' + (bot - 10) + ' ' + (cx - 5) + ' ' + (bot - 12) + ' ' + (cx - 1) + ' ' + (bot - 8) + '\" fill=\"none\" stroke=\"' + S + '\" stroke-width=\"' + (t.key === 'thin' ? 1.1 : 1.8) + '\"/>';\r\n      s += '<path d=\"M' + (cx - 12) + ' ' + (bot - 2) + ' L' + (cx - 18) + ' ' + (bot - 6) + '\" stroke=\"' + S + '\" stroke-width=\"1\"/>';\r\n    }\r\n    return s;\r\n  }\r\n\r\n  /* =========================================================\r\n     渲染\r\n     ========================================================= */\r\n  function render() {\r\n    var c = curCasing();\r\n    var f = FORM_OF(state.form);\r\n    var s = {\r\n      form: state.form, casing: c, drift: c.drift, od: state.od, fishId: state.fishId,\r\n      fishBore: f.bore, len: state.len, incl: state.incl, bottom: state.bottom,\r\n      circ: state.circ, material: state.material, stuck: state.stuck\r\n    };\r\n\r\n    var rows = rank(s);\r\n    var usable = rows.filter(function (r) { return !r.e.out; });\r\n    var best = usable[0] || null;\r\n    var hardCount = rows.length - usable.length;\r\n\r\n    var branchA = null, branchB = null;\r\n    if (state.bottom === null) {\r\n      var sa = clone(s); sa.bottom = true;\r\n      var sb = clone(s); sb.bottom = false;\r\n      branchA = bestOf(rank(sa));\r\n      branchB = bestOf(rank(sb));\r\n    }\r\n\r\n    el('st-tool').textContent = best ? (best.t.name + (state.bottom === null && best.t.needBottom ? '（条件）' : '')) : (state.stuck === 'buried' ? '需先套铣/磨铣' : '无可用工具');\r\n    el('st-score').textContent = best ? best.score.toFixed(2) : '—';\r\n    el('st-trip').textContent = tripText(best);\r\n    el('st-excl').innerHTML = hardCount + ' <small>/ ' + TOOLS.length + ' 件<\/small>';\r\n    el('sch-hint').textContent = state.od + ' mm × ' + fmt1(state.len) + ' m · 通径 ' + fmt1(c.drift) + ' mm';\r\n    el('art-hint').textContent = best ? best.t.name : '—';\r\n    el('art-note').textContent = best ? best.t.note :\r\n      '当前没有通过硬约束的打捞工具。系统不会为了给出答案而推荐物理不可行的工具，应先走套铣/磨铣工序清障。';\r\n    el('toolart').innerHTML = best ? toolArt(best.t.key) : '';\r\n\r\n    /* 排序列表：不可用标红并列出全部原因，可用行 title 带完整规格与备注 */\r\n    var rankNo = 0;\r\n    el('rank').innerHTML = rows.map(function (r) {\r\n      var t = r.t, e = r.e, head;\r\n      if (e.out) {\r\n        return '<div class=\"rankrow out\" title=\"不可用：' + e.why + '｜' + toolTitle(t) + '\">' +\r\n          '<div class=\"l1\"><span class=\"mono\" style=\"font-size:9.5px;color:var(--ink-4)\">—<\/span>' +\r\n          '<span class=\"nm\">' + t.name + '<\/span><span class=\"sc\">不可用<\/span><\/div>' +\r\n          '<div class=\"meta\">' + sizeMeta(t) + '<\/div>' +\r\n          '<div class=\"why\">不可用：' + e.why + '<\/div><\/div>';\r\n      }\r\n      rankNo++;\r\n      var badge = rankNo === 1\r\n        ? (state.bottom === null && t.needBottom ? ' <span class=\"db warn\">条件首选<\/span>' : ' <span class=\"db ok\">首选<\/span>')\r\n        : '';\r\n      head = '<div class=\"l1\"><span class=\"mono\" style=\"font-size:9.5px;color:var(--ink-4)\">' + rankNo + '<\/span>' +\r\n        '<span class=\"nm\">' + t.name + badge + '<\/span>' +\r\n        '<span class=\"sc\">' + e.score.toFixed(2) + '<\/span><\/div>' +\r\n        '<div class=\"dbar\" style=\"margin-top:3px\"><span class=\"track\"><i style=\"width:' + (e.score * 100).toFixed(0) + '%\"><\/i><\/span>' +\r\n        '<span class=\"val\">' + Math.round(e.score * 100) + '%<\/span><\/div>' +\r\n        '<div class=\"meta\">' + sizeMeta(t) + '<\/div>';\r\n      if (e.warns.length) head += '<div class=\"warnline\">' + e.warns.join('；') + '<\/div>';\r\n      return '<div class=\"rankrow\" title=\"' + toolTitle(t) + '\">' + head + '<\/div>';\r\n    }).join('');\r\n\r\n    /* 分项得分 */\r\n    if (best) {\r\n      var clearance = '工具外径 ' + best.t.od + ' mm ≤ 通径 ' + fmt1(c.drift) + ' − 2×6 = ' + fmt1(c.drift - 12) + ' mm';\r\n      var catchTxt = best.t.basis === 'id'\r\n        ? '落物内径 ' + state.fishId + ' mm 在' + best.t.sizeLabel + ' ' + best.t.dmin + '—' + best.t.dmax + ' mm 内'\r\n        : '落物外径 ' + state.od + ' mm 在' + best.t.sizeLabel + ' ' + best.t.dmin + '—' + best.t.dmax + ' mm 内';\r\n      var lenTxt = '落物长度 ' + fmt1(state.len) + ' m ≥ 最小咬合长度 ' + fmt1(best.t.minLen) + ' m';\r\n      el('parts').innerHTML = best.e.parts.map(function (x) {\r\n        return '<div class=\"dbar\" style=\"padding:4px 0\"><span style=\"width:64px;font-size:10.5px\">' + x.k + '<\/span>' +\r\n          '<span class=\"track\"><i style=\"width:' + (x.p * 100).toFixed(0) + '%\"><\/i><\/span>' +\r\n          '<span class=\"val\">' + (x.w * x.p).toFixed(3) + ' / ' + x.w.toFixed(2) + '<\/span><\/div>';\r\n      }).join('') +\r\n        '<div style=\"display:flex;justify-content:space-between;font-size:11px;color:var(--ink-3);border-top:1px solid var(--line);margin-top:6px;padding-top:6px\">' +\r\n        '<span>历史成功率（该工具）<\/span><span class=\"mono\">' + (best.t.succ * 100).toFixed(0) + '%<\/span><\/div>' +\r\n        '<div style=\"font-size:10px;color:var(--ink-3);line-height:1.65;margin-top:5px\">' +\r\n        clearance + '<br>' + catchTxt + '<br>' + lenTxt + '<\/div>';\r\n    } else {\r\n      el('parts').innerHTML = '<div style=\"font-size:11px;color:var(--ink-3);line-height:1.65\">没有可用工具，无法分项评分。' +\r\n        '硬约束已经把所有物理不可行的选项排除，危险推荐率保持 0%。<\/div>';\r\n    }\r\n\r\n    renderOrders(best, usable, branchA, branchB);\r\n    renderPrep(best);\r\n    renderTable(best);\r\n    renderNote(rows, usable, best, branchA, branchB);\r\n    drawSchematic(best);\r\n  }\r\n\r\n  /* ---------- 作业顺序 ---------- */\r\n  function renderOrders(best, usable, branchA, branchB) {\r\n    var o = [];\r\n    var stuck = state.stuck;\r\n    var limit = curCasing().drift - 2 * CLEARANCE;\r\n    var washWarn = PREP[0].od > limit\r\n      ? ' <b>套铣筒 108 mm 超过本井上限 ' + fmt1(limit) + ' mm，需换小一级。<\/b>' : '';\r\n    var basketWarn = PREP[2].od > limit\r\n      ? ' <b>篮式筒 108 mm 超过本井上限 ' + fmt1(limit) + ' mm，需换小一级或改用反循环。<\/b>' : '';\r\n    var circWarn = state.circ ? '' : ' <b>本井不可循环<\/b>，套铣/磨铣/篮式清屑工序不可用，需先恢复循环或改用机械清障。';\r\n\r\n    if (state.bottom === null) {\r\n      o.push('<b>先打印（铅印）确认鱼顶<\/b>：落物是否落底、鱼顶是否规则、是否被砂埋。不要用通井规探底代替打印。');\r\n      o.push('<b>分支 A · 若已落底<\/b>：' + (branchA\r\n        ? '首选 <b>' + branchA.t.name + '<\/b>（' + branchA.score.toFixed(2) + '）；' + branchA.t.op\r\n        : '无工具通过硬约束，先评估套铣/磨铣。'));\r\n      if (branchB && branchA && branchB.t.key === branchA.t.key) {\r\n        o.push('<b>分支 B · 若悬空<\/b>：首选同为 <b>' + branchB.t.name + '<\/b>（' + branchB.score.toFixed(2) + '）；动作同上，但需落底的工具全部不可用。');\r\n      } else {\r\n        o.push('<b>分支 B · 若悬空<\/b>：' + (branchB\r\n          ? '首选 <b>' + branchB.t.name + '<\/b>（' + branchB.score.toFixed(2) + '）；' + branchB.t.op + ' 需落底的工具在这一分支全部不可用。'\r\n          : '没有工具通过硬约束，需先打印鱼顶并评估套铣/磨铣。'));\r\n      }\r\n    }\r\n\r\n    if (best && state.bottom !== null) {\r\n      o.push('<b>本趟<\/b>：' + best.t.op);\r\n    }\r\n    if (best && (stuck === 'sand' || stuck === 'cement')) {\r\n      o.push('<b>工具串<\/b>：' + best.t.name + ' + 震击器 + 安全接头。' +\r\n        (stuck === 'sand' ? '砂卡时遇卡可震击解卡，安全接头保证能丢手退出。' : '水泥卡时先套铣/磨铣解除水泥环，再带震击器与安全接头下打捞工具。'));\r\n    }\r\n\r\n    if (usable[1]) {\r\n      o.push('备选：<b>' + usable[1].t.name + '<\/b>（匹配度 ' + usable[1].score.toFixed(2) + '）。若首选抓空或咬合失败，第二趟直接换它，避免临时找工具。');\r\n    }\r\n\r\n    if (!best) {\r\n      o.push('<b>无直接打捞工具<\/b>：先走工序——' +\r\n        (stuck === 'buried' ? '套铣筒清障 → ' : '') +\r\n        '平底磨鞋磨铣 → 篮式捞筒 / 反循环清屑 → 再评估打捞。不要带着卡瓦类工具硬下。' +\r\n        (stuck === 'buried' ? ' 清障后下打捞工具时，工具串再加震击器 + 安全接头。' : '') + washWarn + basketWarn + circWarn);\r\n    } else if (state.od >= 88) {\r\n      o.push('落物外径 ' + state.od + ' mm 偏大：若首选失败，不要反复下卡瓦类工具，转<b>平底磨鞋 + 篮式捞筒/反循环<\/b>磨铣清屑后再捞。');\r\n    }\r\n\r\n    if (stuck === 'sand' || stuck === 'cement') {\r\n      o.push('<b>解卡前置<\/b>：' + (stuck === 'sand' ? '砂卡先用套铣筒清洗砂桥' : '水泥卡先用套铣筒/平底磨鞋处理水泥环') + '，套铣到位后再下打捞工具；不要用打捞工具直接硬提。' + (best ? washWarn : '') + (best ? circWarn : ''));\r\n    }\r\n\r\n    el('orders').innerHTML = o.map(function (x) { return '<div>' + x + '<\/div>'; }).join('');\r\n  }\r\n\r\n  /* ---------- 解卡 / 磨铣工序面板 ---------- */\r\n  function renderPrep(best) {\r\n    var stuck = state.stuck;\r\n    var c = curCasing();\r\n    var limit = c.drift - 2 * CLEARANCE;\r\n    var washFit = PREP[0].od <= limit;\r\n    var seq;\r\n    if (stuck === 'buried') {\r\n      seq = '<b>落物被埋<\/b>：鱼顶不可达，直接打捞工具已全部被硬约束排除。顺序：<b>套铣筒 → 平底磨鞋 → 篮式捞筒 / 反循环 → 打捞工具<\/b>；清障后下打捞工具时，工具串再加<b>震击器 + 安全接头<\/b>。';\r\n    } else if (stuck === 'sand') {\r\n      seq = '<b>砂卡<\/b>：先下<b>套铣筒<\/b>清洗砂桥，再下打捞工具；工具串加<b>震击器 + 安全接头<\/b>。平底磨鞋只在鱼顶不规则时使用。';\r\n    } else if (stuck === 'cement') {\r\n      seq = '<b>水泥卡<\/b>：套铣筒磨铣水泥环，必要时用平底磨鞋修整鱼顶，篮式捞筒/反循环清屑后再捞。';\r\n    } else if (!best) {\r\n      seq = '<b>无直接打捞工具<\/b>：改走磨铣工序——<b>平底磨鞋 + 篮式捞筒 / 反循环<\/b>清屑，再评估打捞。';\r\n    } else {\r\n      seq = '<b>当前未卡阻<\/b>：打捞工具可直接接触鱼顶，不需要套铣/磨铣。若后续出现砂卡、水泥卡或落物被埋，再启用下列工序。';\r\n    }\r\n    if (!washFit && stuck !== 'none') {\r\n      seq += ' <b>注意<\/b>：套铣筒外径 108 mm 超过本井工具外径上限 ' + fmt1(limit) + ' mm，需换小一级套铣筒。';\r\n    }\r\n    var prepBad = PREP.some(function (p) {\r\n      return (p.circ && !state.circ) || p.od > limit;\r\n    });\r\n    if (prepBad && (stuck !== 'none' || !best)) {\r\n      seq += ' <b>注意<\/b>：标「不可用」的工序工具不满足通径或循环条件，不能下；先恢复循环或换小一级工具。';\r\n    }\r\n    if (!best && stuck === 'none') {\r\n      seq += ' 本井工具外径上限 ' + fmt1(limit) + ' mm，选工序工具时同样要校核通径。';\r\n    }\r\n\r\n    var rows = PREP.map(function (p) {\r\n      var pass = p.od <= limit;\r\n      var circOk = !p.circ || state.circ;\r\n      var bad = [];\r\n      if (!pass) bad.push('外径超过本井上限 ' + fmt1(limit) + ' mm，需换小一级');\r\n      if (!circOk) bad.push('需循环，本井不可循环');\r\n      var status = '待用', cls = 'plain';\r\n      if (bad.length) { status = '不可用'; cls = 'bad'; }\r\n      else if (stuck === 'buried') { status = '适用'; cls = 'ok'; }\r\n      else if (stuck === 'sand' || stuck === 'cement') {\r\n        if (p.key === 'wash') { status = '先做'; cls = 'ok'; }\r\n        else if (p.key === 'mill') { status = '视情况'; cls = 'warn'; }\r\n        else { status = '随后清屑'; cls = 'plain'; }\r\n      } else if (!best) {\r\n        if (p.key === 'wash') { status = '视情况'; cls = 'warn'; }\r\n        else { status = '推荐'; cls = 'ok'; }\r\n      }\r\n      var fitTxt = bad.length ? ' · ' + bad.join('；') : '';\r\n      return '<div class=\"prep-row\"><div class=\"pn\">' + p.name + '<\/div>' +\r\n        '<div class=\"pd\">' + p.note + '<br><em>外径 ' + p.od + ' mm · ' + p.when + ' · 需循环 ' + (p.circ ? '是' : '否') + fitTxt + '<\/em><\/div>' +\r\n        '<div><span class=\"db ' + cls + '\">' + status + '<\/span><\/div><\/div>';\r\n    }).join('');\r\n\r\n    el('prep').innerHTML = '<div class=\"prep-seq\">' + seq + '<\/div>' + rows;\r\n  }\r\n\r\n  /* ---------- 工具尺寸表 ---------- */\r\n  function renderTable(best) {\r\n    var head = '<div class=\"tblwrap\"><table class=\"ttbl\"><colgroup>' +\r\n      '<col style=\"width:12%\"><col style=\"width:6%\"><col style=\"width:15%\"><col style=\"width:13%\">' +\r\n      '<col style=\"width:6%\"><col style=\"width:6%\"><col style=\"width:7%\"><col style=\"width:7%\"><col style=\"width:28%\">' +\r\n      '<\/colgroup><thead><tr><th>工具<\/th><th>外径<\/th><th>内孔 / 可捞区间<\/th><th>适用形态<\/th>' +\r\n      '<th>落底<\/th><th>循环<\/th><th>最大井斜<\/th><th>成功率<\/th><th>备注<\/th><\/tr><\/thead><tbody>';\r\n\r\n    var body = TOOLS.map(function (t) {\r\n      var cid = (t.bore ? t.bore : '—') + ' / ' + (t.basis === 'id' ? '内径 ' : '') + t.dmin + '—' + t.dmax;\r\n      var isBest = best && best.t.key === t.key;\r\n      return '<tr' + (isBest ? ' class=\"best\"' : '') + ' title=\"' + t.note + '\">' +\r\n        '<td class=\"tn\">' + t.name + '<\/td>' +\r\n        '<td class=\"num\">' + t.od + '<\/td>' +\r\n        '<td class=\"cid\">' + cid + '<\/td>' +\r\n        '<td>' + formNames(t) + '<\/td>' +\r\n        '<td class=\"num\">' + (t.needBottom ? '是' : '否') + '<\/td>' +\r\n        '<td class=\"num\">' + (t.circ ? '是' : '否') + '<\/td>' +\r\n        '<td class=\"num\">' + t.maxIncl + '°<\/td>' +\r\n        '<td class=\"num\">' + Math.round(t.succ * 100) + '%<\/td>' +\r\n        '<td class=\"note\">' + t.note + '<\/td><\/tr>';\r\n    }).join('');\r\n\r\n    var cap = '<div class=\"tblcap\"><b>读表约定<\/b>：外部套入式工具必须满足「可捞上限 dmax &lt; 工具内孔 &lt; 工具外径」，' +\r\n      '否则落物进不去或工具进不了套管；<b>公锥 / 捞矛<\/b>按落物内径选型，<b>母锥 / 卡瓦筒<\/b>按落物外径选型。' +\r\n      '套铣筒与平底磨鞋是解卡/磨铣工序工具，不进入打捞排序。<\/div>';\r\n\r\n    el('tooltable').innerHTML = head + body + '<\/tbody><\/table><\/div>' + cap;\r\n  }\r\n\r\n  /* ---------- 教学说明 ---------- */\r\n  function renderNote(rows, usable, best, branchA, branchB) {\r\n    var f = FORM_OF(state.form), c = curCasing();\r\n    var txt = '当前落物：<b>' + f.name + '<\/b>（' + f.desc + '），外径 ' + state.od + ' mm' +\r\n      (f.bore ? (state.fishId > 0 ? '、内径 ' + state.fishId + ' mm' : '、内径未给出') : '、无内孔') +\r\n      '、长 ' + fmt1(state.len) + ' m；套管 <b>' + c.label + '<\/b>（通径 ' + fmt1(c.drift) + ' mm，工具外径上限 ' + fmt1(c.drift - 12) + ' mm）；' +\r\n      '井斜 ' + state.incl + '°；' +\r\n      (state.bottom === true ? '<b>已落底<\/b>' : (state.bottom === false ? '<b>悬空<\/b>' : '落底状态<b>未知<\/b>（默认给两分支）')) +\r\n      '；' + (state.circ ? '可循环洗井' : '不可循环') + '；' + (state.material === 'ferro' ? '铁磁性' : '非铁磁性') +\r\n      '；卡阻状态：' + (state.stuck === 'none' ? '未卡阻' : (state.stuck === 'sand' ? '砂卡' : (state.stuck === 'cement' ? '水泥卡' : '落物被埋'))) + '。';\r\n\r\n    txt += ' 硬约束排除了 <b>' + (rows.length - usable.length) + '<\/b> 件，剩余 <b>' + usable.length + '<\/b> 件参与评分。';\r\n    if (best) {\r\n      txt += ' 首选 <b>' + best.t.name + '<\/b>，匹配度 <b>' + best.score.toFixed(2) + '<\/b>，预计起下钻 <b>' + tripText(best) + '<\/b>。';\r\n      txt += state.bottom === null\r\n        ? ' 进入排序的工具全部通过外径/通径、可捞区间、材质、井斜、循环、咬合长度六类硬约束；落底未知时，需落底工具只作条件推荐（悬空分支不可用）。<b>危险推荐率 0%<\/b>。'\r\n        : ' 进入排序的工具全部通过外径/通径、可捞区间、材质、井斜、循环、落底、咬合长度七类硬约束，<b>危险推荐率 0%<\/b>。';\r\n    } else {\r\n      txt += ' 当前没有通过硬约束的打捞工具——<b>危险推荐率 0%<\/b>，系统不会为了给答案而推荐物理不可行项。';\r\n    }\r\n    if (state.bottom === null) {\r\n      txt += ' 落底分支：' + (branchA ? '<b>' + branchA.t.name + '<\/b>（' + branchA.score.toFixed(2) + '）' : '无') +\r\n        '；悬空分支：' + (branchB ? '<b>' + branchB.t.name + '<\/b>（' + branchB.score.toFixed(2) + '）' : '无可用工具') + '。';\r\n    }\r\n\r\n    var tip;\r\n    if (state.stuck === 'buried') {\r\n      tip = ' 落物被埋时鱼顶不可达，所有直接打捞工具都被排除，应先套铣/磨铣清障——这是“先清障、后打捞”的硬顺序。';\r\n    } else if (state.casing === 1) {\r\n      tip = ' 5-1/2\" 23# 的通径只有 118.6 mm，按单边 6 mm 间隙工具外径上限 106.6 mm；外径 108 mm 的卡瓦打捞筒与篮式捞筒已被排除——校核必须用通径，不能用套管外径。';\r\n    } else if (state.od >= 100) {\r\n      tip = ' 落物外径 ≥100 mm 已超过卡瓦筒/母锥的可捞上限，直接打捞不可行，只能先磨铣/套铣；这正是“大件先磨后捞”的现场逻辑。';\r\n    } else if (state.form === 'cable' && state.incl >= 60) {\r\n      tip = ' 大斜度井里电缆贴壁，绳类打捞钩的钩挂窗口很窄；细钢丝捞钩允许井斜只有 55°，在 60° 以上井里已被硬约束排除。';\r\n    } else if (state.bottom === null) {\r\n      tip = ' 落底状态默认“未知”：需落底的一把抓只给条件推荐，先铅印打印鱼顶，再按落底/悬空两个分支选工具。';\r\n    } else {\r\n      tip = ' 试试把套管切到 5-1/2\" 23#：工具外径上限降到 106.6 mm，108 mm 的卡瓦筒会立刻被排除；再把落物外径拖到 110 mm，所有卡瓦类工具都会失效，只剩磨铣/套铣工序。';\r\n    }\r\n    el('note').innerHTML = txt + tip;\r\n  }\r\n\r\n  /* =========================================================\r\n     控件\r\n     ========================================================= */\r\n  function setSeg(id, attr, val) {\r\n    var box = el(id);\r\n    if (!box) return;\r\n    [].forEach.call(box.children, function (b) {\r\n      b.classList.toggle('on', b.getAttribute(attr) === String(val));\r\n    });\r\n  }\r\n\r\n  function syncControls() {\r\n    var c = curCasing();\r\n    var f = FORM_OF(state.form);\r\n    var maxOd = Math.max(1, Math.floor(c.drift - 1));\r\n\r\n    if (state.od > maxOd) state.od = maxOd;\r\n    if (state.od < 1) state.od = 1;\r\n    var idMax = Math.max(0, state.od - 6);\r\n    if (!f.bore) state.fishId = 0;\r\n    if (state.fishId > idMax) state.fishId = idMax;\r\n    if (state.fishId < 0) state.fishId = 0;\r\n\r\n    el('r-od').max = maxOd;\r\n    el('r-od').value = state.od;\r\n    el('o-od').textContent = state.od + ' mm';\r\n\r\n    el('r-fid').max = Math.max(1, idMax);\r\n    el('r-fid').value = state.fishId;\r\n    el('r-fid').disabled = !f.bore;\r\n    el('o-fid').textContent = f.bore ? (state.fishId > 0 ? (state.fishId + ' mm') : '未给出') : '无内孔';\r\n\r\n    el('r-len').value = state.len;\r\n    el('o-len').textContent = fmt1(state.len) + ' m';\r\n    el('r-incl').value = state.incl;\r\n    el('o-incl').textContent = state.incl + '°';\r\n\r\n    el('casing-hint').textContent = '通径 ' + fmt1(c.drift) + ' mm · 工具外径 ≤ ' + fmt1(c.drift - 12) + ' mm（单边 6 mm）';\r\n\r\n    setSeg('seg-form', 'data-f', state.form);\r\n    setSeg('seg-casing', 'data-v', state.casing);\r\n    setSeg('seg-bottom', 'data-b', state.bottom === null ? 'u' : (state.bottom ? '1' : '0'));\r\n    setSeg('seg-mat', 'data-m', state.material);\r\n    setSeg('seg-stuck', 'data-s', state.stuck);\r\n    el('tog-circ').classList.toggle('on', state.circ);\r\n  }\r\n\r\n  function applyForm(k) {\r\n    var f = FORM_OF(k);\r\n    var maxOd = Math.max(1, Math.floor(curCasing().drift - 1));\r\n    state.form = k;\r\n    state.od = clamp(f.od, 1, maxOd);\r\n    state.len = clamp(f.len, 0.1, 12);\r\n    state.fishId = f.bore ? clamp(f.fid, 0, Math.max(0, state.od - 6)) : 0;\r\n    syncControls();\r\n    render();\r\n  }\r\n\r\n  function init() {\r\n    el('seg-form').innerHTML = FORMS.map(function (f) {\r\n      return '<button type=\"button\" data-f=\"' + f.key + '\" title=\"' + f.desc + '\">' + f.name + '<\/button>';\r\n    }).join('');\r\n\r\n    el('seg-casing').innerHTML = CASINGS.map(function (c, i) {\r\n      return '<button type=\"button\" data-v=\"' + i + '\" title=\"' + c.label.replace(/\"/g, '&quot;') + ' 通径 ' + fmt1(c.drift) + ' mm\">' + c.label + '<\/button>';\r\n    }).join('');\r\n\r\n    el('seg-form').addEventListener('click', function (e) {\r\n      var b = e.target.closest('button');\r\n      if (!b) return;\r\n      applyForm(b.getAttribute('data-f'));\r\n    });\r\n\r\n    el('seg-casing').addEventListener('click', function (e) {\r\n      var b = e.target.closest('button');\r\n      if (!b) return;\r\n      state.casing = Number(b.getAttribute('data-v'));\r\n      syncControls();\r\n      render();\r\n    });\r\n\r\n    el('seg-bottom').addEventListener('click', function (e) {\r\n      var b = e.target.closest('button');\r\n      if (!b) return;\r\n      var v = b.getAttribute('data-b');\r\n      state.bottom = v === '1' ? true : (v === '0' ? false : null);\r\n      syncControls();\r\n      render();\r\n    });\r\n\r\n    el('seg-mat').addEventListener('click', function (e) {\r\n      var b = e.target.closest('button');\r\n      if (!b) return;\r\n      state.material = b.getAttribute('data-m');\r\n      syncControls();\r\n      render();\r\n    });\r\n\r\n    el('seg-stuck').addEventListener('click', function (e) {\r\n      var b = e.target.closest('button');\r\n      if (!b) return;\r\n      state.stuck = b.getAttribute('data-s');\r\n      syncControls();\r\n      render();\r\n    });\r\n\r\n    el('tog-circ').addEventListener('click', function () {\r\n      state.circ = !state.circ;\r\n      syncControls();\r\n      render();\r\n    });\r\n\r\n    function bindSlider(id, key, isFloat) {\r\n      var r = el(id);\r\n      r.addEventListener('input', function () {\r\n        state[key] = isFloat ? Number(r.value) : Math.round(Number(r.value));\r\n        syncControls();\r\n        render();\r\n      });\r\n    }\r\n    bindSlider('r-od', 'od', false);\r\n    bindSlider('r-fid', 'fishId', false);\r\n    bindSlider('r-len', 'len', true);\r\n    bindSlider('r-incl', 'incl', false);\r\n\r\n    el('btn-reset').addEventListener('click', function () {\r\n      state = clone(DEFAULTS);\r\n      syncControls();\r\n      render();\r\n    });\r\n\r\n    syncControls();\r\n    render();\r\n  }\r\n\r\n  init();\r\n})();\r\n"},{"name":"demo/index.html","size":8476,"mime":"text/plain","enc":"text","data":"<!DOCTYPE html>\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>示范：落物打捞工具智能选型<\/title>\r\n<link rel=\"stylesheet\" href=\"demo.css\">\r\n<style>\r\n  .rankrow{display:grid;grid-template-columns:1fr;gap:2px;padding:6px 0;border-bottom:1px solid var(--line)}\r\n  .rankrow:last-child{border-bottom:0}\r\n  .rankrow .l1{display:grid;grid-template-columns:20px 1fr auto;gap:8px;align-items:baseline}\r\n  .rankrow .nm{font-size:12.5px;font-weight:600;color:var(--ink)}\r\n  .rankrow .sc{font-family:var(--mono);font-size:11.5px;color:var(--jade-d)}\r\n  .rankrow.out .nm{color:var(--ink-4);font-weight:500}\r\n  .rankrow.out .sc{color:var(--ink-4)}\r\n  .rankrow .why{font-size:10.5px;color:var(--ink-4);line-height:1.5}\r\n  .rankrow .meta{font-size:9.5px;color:var(--ink-4);line-height:1.45;font-family:var(--mono)}\r\n  .rankrow .warnline{font-size:10px;color:var(--warn);line-height:1.5}\r\n  .rankrow.out .why{color:var(--bad)}\r\n  .ordlist{counter-reset:o;font-size:11.5px;color:var(--ink-2);line-height:1.7}\r\n  .ordlist div{padding:5px 0 5px 22px;position:relative;border-bottom:1px solid var(--line)}\r\n  .ordlist div:last-child{border-bottom:0}\r\n  .ordlist div::before{counter-increment:o;content:counter(o);position:absolute;left:0;top:6px;width:15px;height:15px;border-radius:4px;background:var(--jade-l);color:var(--jade-d);font-family:var(--mono);font-size:9px;display:grid;place-items:center}\r\n  .dctl.sub{padding-top:8px}\r\n  .seg.sm button{padding:2px 8px;font-size:10.5px}\r\n  .hint{font-family:var(--mono);font-size:9px;color:var(--ink-4);white-space:nowrap}\r\n  .dctl input[type=range]{width:112px}\r\n  .prep-seq{font-size:11.5px;color:var(--ink-2);line-height:1.65;background:var(--card-soft);border:1px solid var(--line);border-radius:7px;padding:7px 10px;margin-bottom:4px}\r\n  .prep-seq b{color:var(--ink)}\r\n  .prep-row{display:grid;grid-template-columns:78px minmax(0,1fr) auto;gap:10px;align-items:start;padding:7px 0;border-bottom:1px solid var(--line)}\r\n  .prep-row:last-child{border-bottom:0}\r\n  .prep-row .pn{font-size:11.5px;font-weight:600;color:var(--ink)}\r\n  .prep-row .pd{font-size:10.5px;color:var(--ink-3);line-height:1.55}\r\n  .prep-row .pd em{font-style:normal;color:var(--ink-4);font-family:var(--mono);font-size:9px}\r\n  .tblwrap{overflow-x:auto}\r\n  .ttbl{width:100%;border-collapse:collapse;table-layout:fixed;font-size:10px;line-height:1.5}\r\n  .ttbl th{font-family:var(--mono);font-size:8px;letter-spacing:.05em;color:var(--ink-4);font-weight:400;text-align:left;padding:5px 6px 5px 0;border-bottom:1px solid var(--line-2);white-space:nowrap}\r\n  .ttbl td{padding:5px 6px 5px 0;border-bottom:1px solid var(--line);color:var(--ink-2);vertical-align:top}\r\n  .ttbl tr:last-child td{border-bottom:0}\r\n  .ttbl tr.best td{background:rgba(36,92,90,.05)}\r\n  .ttbl .tn{font-weight:600;color:var(--ink)}\r\n  .ttbl .num{font-family:var(--mono);font-size:9.5px;white-space:nowrap}\r\n  .ttbl .note{font-size:9px;color:var(--ink-3);line-height:1.45}\r\n  .ttbl .cid{font-family:var(--mono);font-size:9px}\r\n  .tblcap{font-size:10.5px;color:var(--ink-4);line-height:1.65;margin-top:7px;border-top:1px solid var(--line);padding-top:6px}\r\n  .tblcap b{color:var(--ink-3)}\r\n  @media (min-width:901px){.dgrid.c2b{grid-template-columns:minmax(0,380px) minmax(0,1fr)}}\r\n  #sch-hint{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}\r\n<\/style>\r\n<\/head>\r\n<body>\r\n\r\n<div class=\"dhead\">\r\n  <div>\r\n    <div class=\"dkick\">TOOL SELECTION · 规则匹配<\/div>\r\n    <h1>落物特征 → 打捞工具适用性排序<\/h1>\r\n    <p class=\"lead\">先设定落物形态与井况，<b>硬约束<\/b>把物理上不可能的选项剔掉（工具外径 + 单边间隙、通径、可捞外径/内径区间、材质、井斜、循环、落底、最小咬合长度），\r\n    再用<b>软评分<\/b>给剩下的工具排序。左边井筒剖面上会画出首选工具的下入状态；套铣筒与平底磨鞋只作为<b>解卡/磨铣工序工具<\/b>，不参与打捞排序。<\/p>\r\n  <\/div>\r\n  <div class=\"dhead-r\">\r\n    <div class=\"dstat\"><div class=\"k\">首选工具<\/div><div class=\"v\" id=\"st-tool\" style=\"font-size:12px\">—<\/div><\/div>\r\n    <div class=\"dstat\"><div class=\"k\">匹配度<\/div><div class=\"v\" id=\"st-score\">—<\/div><\/div>\r\n    <div class=\"dstat\"><div class=\"k\">预计起下钻<\/div><div class=\"v\" id=\"st-trip\">—<\/div><\/div>\r\n    <div class=\"dstat\"><div class=\"k\">硬约束拦截<\/div><div class=\"v\" id=\"st-excl\">—<\/div><\/div>\r\n  <\/div>\r\n<\/div>\r\n\r\n<div class=\"dctl\">\r\n  <div class=\"grp\"><span class=\"glbl\">落物形态<\/span><div class=\"seg\" id=\"seg-form\"><\/div><\/div>\r\n  <div class=\"grp\"><span class=\"glbl\">套管规格<\/span><div class=\"seg\" id=\"seg-casing\"><\/div><span class=\"hint\" id=\"casing-hint\">—<\/span><\/div>\r\n  <div class=\"ctl-s\"><label>落物外径<\/label><input type=\"range\" id=\"r-od\" min=\"1\" max=\"120\" step=\"1\" value=\"73\"><output id=\"o-od\">73 mm<\/output><\/div>\r\n  <div class=\"ctl-s\"><label>落物内径<\/label><input type=\"range\" id=\"r-fid\" min=\"0\" max=\"67\" step=\"1\" value=\"62\"><output id=\"o-fid\">62 mm<\/output><\/div>\r\n  <div class=\"ctl-s\"><label>长度<\/label><input type=\"range\" id=\"r-len\" min=\"0.1\" max=\"12\" step=\"0.1\" value=\"2.4\"><output id=\"o-len\">2.4 m<\/output><\/div>\r\n  <div class=\"ctl-s\"><label>井斜<\/label><input type=\"range\" id=\"r-incl\" min=\"0\" max=\"70\" step=\"1\" value=\"18\"><output id=\"o-incl\">18°<\/output><\/div>\r\n<\/div>\r\n\r\n<div class=\"dctl sub\">\r\n  <div class=\"grp\"><span class=\"glbl\">落底状态<\/span><div class=\"seg sm\" id=\"seg-bottom\">\r\n    <button data-b=\"1\">已落底<\/button><button data-b=\"0\">悬空<\/button><button data-b=\"u\" class=\"on\">未知<\/button>\r\n  <\/div><\/div>\r\n  <div class=\"grp\"><span class=\"glbl\">落物材质<\/span><div class=\"seg sm\" id=\"seg-mat\">\r\n    <button data-m=\"ferro\" class=\"on\">铁磁性<\/button><button data-m=\"non\">非铁磁性<\/button>\r\n  <\/div><\/div>\r\n  <label class=\"tog on\" id=\"tog-circ\"><i><\/i>可循环洗井<\/label>\r\n  <div class=\"grp\"><span class=\"glbl\">卡阻状态<\/span><div class=\"seg sm\" id=\"seg-stuck\">\r\n    <button data-s=\"none\" class=\"on\">未卡阻<\/button><button data-s=\"sand\">砂卡<\/button><button data-s=\"cement\">水泥卡<\/button><button data-s=\"buried\">被埋<\/button>\r\n  <\/div><\/div>\r\n  <span class=\"sp\"><\/span>\r\n  <button class=\"dbtn reset\" id=\"btn-reset\" type=\"button\">↺ 重置<\/button>\r\n<\/div>\r\n\r\n<div class=\"dgrid c2b\">\r\n  <div class=\"dcol\">\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>井筒剖面 · 下入状态<\/b><span id=\"sch-hint\">落物 73 mm · 2.4 m<\/span><\/div>\r\n      <svg id=\"schematic\" viewBox=\"0 0 380 440\" role=\"img\" aria-label=\"井筒与落物打捞示意\"><\/svg>\r\n      <div class=\"dfig-foot\">\r\n        <span><i style=\"background:#d3c9b6\"><\/i>套管<\/span>\r\n        <span><i style=\"background:#a64b3c\"><\/i>落物<\/span>\r\n        <span><i style=\"background:#1d4e50\"><\/i>推荐工具<\/span>\r\n        <span>井斜按 0.45 比例绘制 · 示意，非等比例<\/span>\r\n      <\/div>\r\n    <\/div>\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>首选工具构造示意<\/b><span id=\"art-hint\">—<\/span><\/div>\r\n      <svg id=\"toolart\" viewBox=\"0 0 210 172\" role=\"img\" aria-label=\"工具构造\"><\/svg>\r\n      <p style=\"font-size:11px;color:var(--ink-3);line-height:1.65;margin-top:6px\" id=\"art-note\">—<\/p>\r\n    <\/div>\r\n  <\/div>\r\n\r\n  <div class=\"dcol\">\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>打捞工具适用性排序<\/b><span>灰字 = 被硬约束排除 · 悬停看规格与备注<\/span><\/div>\r\n      <div id=\"rank\"><\/div>\r\n    <\/div>\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>首选工具的分项得分<\/b><span>加权求和 = 匹配度<\/span><\/div>\r\n      <div id=\"parts\"><\/div>\r\n    <\/div>\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>建议作业顺序<\/b><span>按工具类型给动作，不套统一压重<\/span><\/div>\r\n      <div class=\"ordlist\" id=\"orders\"><\/div>\r\n    <\/div>\r\n  <\/div>\r\n<\/div>\r\n\r\n<div class=\"dfig\" style=\"margin-top:12px\">\r\n  <div class=\"dfig-h\"><b>解卡 / 套铣准备（工序工具，不参与打捞评分）<\/b><span>只按卡阻状态推荐<\/span><\/div>\r\n  <div id=\"prep\"><\/div>\r\n<\/div>\r\n\r\n<div class=\"dfig\" style=\"margin-top:12px\">\r\n  <div class=\"dfig-h\"><b>工具尺寸表 · 知识表原文<\/b><span>外径 / 内孔 / 可捞区间 / 工况<\/span><\/div>\r\n  <div id=\"tooltable\"><\/div>\r\n<\/div>\r\n\r\n<p class=\"dnote\" id=\"note\"><\/p>\r\n\r\n<script src=\"demo.js\"><\/script>\r\n<\/body>\r\n<\/html>\r\n"}];
  var PKG = {"id":"fishing-tool-kg","sceneId":"wo2","methods":["kg"],"title":"落物打捞工具智能选型：匹配矩阵","version":"1.1.0","updated":"2026-10-30","status":"ready","tabs":{"background":{"label":"专业背景","lede":"井下落物（油管、抽油杆、电缆、钢球、井下工具）形态各异，打捞工具的选择取决于落物尺寸、形态、所在井段与井身结构。现场的做法常常是「带四套工具下去试试看」——这是修井里最典型的「用起下钻次数换判断力」。本案例把工具手册变成一张可计算的匹配矩阵，用硬约束 + 软评分把「该带哪几套」算出来。","judge":[{"label":"任务类型","value":"分类 + 规则匹配","desc":"落物形态分类 → 工具适用性排序"},{"label":"数据门槛","value":"300—1000 例","desc":"打捞记录 + 工具规格台账"},{"label":"可见收益","value":"示范默认 1 趟","desc":"单井次省 1—2 天工期"},{"label":"难度","value":"中","desc":"落物描述是文本，需先结构化","html":"<span class='dtag' data-d='中'>难度 中<\/span>"}],"sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>落物打捞的难点<b>不在操作，在判断<\/b>：同样是一根断脱的油管，落底与悬空要用不同的工具，井斜 40° 的井里「一把抓」成功率会明显下降，而铁磁性小件用磁力打捞器一次就上来。这些判断现在全在打捞工程师的经验里，工具手册只给规格、不给选择策略。<\/p><p>于是现场普遍采用「多带几套」的保险做法：一趟钻带 3—4 套工具，用掉 1 套。多一次起下钻大约 1—2 天、十几万元——一个区块一年几十井次，这笔钱非常可观。<\/p><div class='figure'><svg viewBox='0 0 660 210' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='多带工具的代价'><rect x='10' y='20' width='286' height='176' rx='9' fill='#fdfcf9' stroke='#e3dccd'/><text x='28' y='40' font-size='9.5' font-family='monospace' fill='#99a3a4' letter-spacing='1.2'>井口 · 一趟钻带下去的工具<\/text><rect x='30' y='52' width='56' height='120' rx='4' fill='#efe9dd' stroke='#d3c9b6'/><rect x='96' y='52' width='56' height='120' rx='4' fill='#efe9dd' stroke='#d3c9b6'/><rect x='162' y='52' width='56' height='120' rx='4' fill='#e7eee9' stroke='#c8dbd2'/><rect x='228' y='52' width='56' height='120' rx='4' fill='#efe9dd' stroke='#d3c9b6'/><text x='58' y='108' font-size='9.5' fill='#6f7a7c' text-anchor='middle'>卡瓦<\/text><text x='58' y='122' font-size='9.5' fill='#6f7a7c' text-anchor='middle'>打捞筒<\/text><text x='124' y='108' font-size='9.5' fill='#6f7a7c' text-anchor='middle'>一把抓<\/text><text x='124' y='122' font-size='9.5' fill='#6f7a7c' text-anchor='middle'>（备选）<\/text><text x='190' y='108' font-size='9.5' fill='#123a3d' text-anchor='middle'>磁力<\/text><text x='190' y='122' font-size='9.5' fill='#123a3d' text-anchor='middle'>打捞器<\/text><text x='256' y='108' font-size='9.5' fill='#6f7a7c' text-anchor='middle'>磨鞋<\/text><text x='256' y='122' font-size='9.5' fill='#6f7a7c' text-anchor='middle'>（未用）<\/text><text x='30' y='186' font-size='10' fill='#a64b3c'>带 4 套下去 · 只有 1 套用上 · 其余重新起下<\/text><rect x='336' y='20' width='314' height='176' rx='9' fill='#faf7f0' stroke='#c8d9d1'/><text x='354' y='40' font-size='9.5' font-family='monospace' fill='#1d4e50' letter-spacing='1.2'>每多一次起下钻的代价<\/text><rect x='364' y='146' width='34' height='30' fill='#c8dbd2'/><rect x='404' y='126' width='34' height='50' fill='#9ab8ac'/><rect x='444' y='98' width='34' height='78' fill='#5f8f7f'/><text x='381' y='140' font-size='9' fill='#4a585c' text-anchor='middle'>1 次<\/text><text x='421' y='120' font-size='9' fill='#4a585c' text-anchor='middle'>2 次<\/text><text x='461' y='92' font-size='9' fill='#4a585c' text-anchor='middle'>3 次<\/text><text x='381' y='186' font-size='9' fill='#99a3a4' text-anchor='middle'>3 天<\/text><text x='421' y='186' font-size='9' fill='#99a3a4' text-anchor='middle'>5 天<\/text><text x='461' y='186' font-size='9' fill='#99a3a4' text-anchor='middle'>8 天<\/text><text x='516' y='104' font-size='10.5' fill='#123a3d'>工期随起下钻次数<\/text><text x='516' y='122' font-size='10.5' fill='#123a3d'>近似线性增长<\/text><text x='516' y='146' font-size='10' fill='#a64b3c'>单井次成本 30 → 100 万元<\/text><text x='516' y='166' font-size='10' fill='#6f7a7c'>「多带一套」的保险<\/text><text x='516' y='182' font-size='10' fill='#6f7a7c'>其实是把成本推给工期<\/text><\/svg><\/div><div class='figcap'><b>图 1<\/b><span>把工具选型做对，等于直接把起下钻次数从 2—3 次压到 1 趟（示范默认）。这是修井环节里<b>投入产出最直接<\/b>的一个智能化切口：不需要新的井下工具，只需要更准的判断。<\/span><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>做法分两步。第一步把工具手册变成<b>结构化的适用条件<\/b>：每件工具写成一条记录——工具外径、内孔、可捞落物外径或内径区间、最小咬合长度 / 最大容纳长度、允许最大井斜、是否需循环、是否需落底、历史成功率。这里有一条硬性的几何关系：<b>外部套入式工具必须满足「可捞上限 &lt; 工具内孔 &lt; 工具外径」<\/b>，否则落物进不去，或者工具根本进不了套管。公锥、捞矛按<b>落物内径<\/b>选型，母锥、卡瓦筒按<b>落物外径<\/b>选型，不能用同一个区间糊过去。<\/p><p>第二步把落物描述也变成结构化输入（形态、外径、内径、长度、材质、井斜、落底三态、能否循环、卡阻状态），然后做<b>两级筛选<\/b>：<\/p><p><b>硬约束真排除<\/b>：工具外径 + 单边 6 mm 间隙超过套管内<b>通径<\/b>、落物外径 / 内径超出可捞区间、磁力打捞器吸非铁磁性落物、井斜超过工具允许值、需循环但本井不能循环、需落底但落物悬空、落物长度小于最小咬合长度或大于工具可容纳长度——这些选项直接标「不可用」，不进入推荐，也不靠扣分蒙混。<b>软评分<\/b>再对剩下的候选按「形态匹配 × 0.32 + 尺寸隶属度 × 0.26 + 井斜适应性 × 0.16 + 历史成功率 × 0.16 + 工况条件 × 0.10」排序，输出首选 + 备选与每一分的理由；落物卡阻或砂埋时，在推荐工具后追加<b>震击器 + 安全接头<\/b>的工具串。<\/p><div class='figure'><svg viewBox='0 0 660 250' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='落物形态与打捞工具匹配矩阵'><text x='16' y='18' font-size='9.5' font-family='monospace' fill='#99a3a4' letter-spacing='1.2'>匹配矩阵 · 行 = 落物形态，列 = 打捞工具（色深 = 形态适用度）<\/text><g font-size='8.5' fill='#99a3a4' text-anchor='middle'><text x='100' y='28'>卡瓦<\/text><text x='100' y='38'>打捞筒<\/text><text x='150' y='28'>小径<\/text><text x='150' y='38'>卡瓦筒<\/text><text x='200' y='28'>母锥<\/text><text x='250' y='28'>公锥<\/text><text x='300' y='28'>捞矛<\/text><text x='350' y='28'>一把抓<\/text><text x='400' y='28'>磁力<\/text><text x='400' y='38'>打捞器<\/text><text x='450' y='28'>篮式<\/text><text x='450' y='38'>捞筒<\/text><text x='500' y='28'>绳类<\/text><text x='500' y='38'>打捞钩<\/text><text x='550' y='28'>细钢丝<\/text><text x='550' y='38'>捞钩<\/text><text x='600' y='28'>抽油杆<\/text><text x='600' y='38'>打捞筒<\/text><\/g><g font-size='10' fill='#4a585c'><text x='16' y='67'>管状体<\/text><text x='16' y='101'>杆状体<\/text><text x='16' y='135'>柔索类<\/text><text x='16' y='169'>实心小件<\/text><text x='16' y='203'>大直径工具<\/text><\/g><rect x='78' y='50' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='128' y='50' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='178' y='50' width='44' height='26' rx='3' fill='#5f8f7f'/><rect x='228' y='50' width='44' height='26' rx='3' fill='#5f8f7f'/><rect x='278' y='50' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='328' y='50' width='44' height='26' rx='3' fill='#d7e3dd'/><rect x='378' y='50' width='44' height='26' rx='3' fill='#eae6db'/><rect x='428' y='50' width='44' height='26' rx='3' fill='#eae6db'/><rect x='478' y='50' width='44' height='26' rx='3' fill='#eae6db'/><rect x='528' y='50' width='44' height='26' rx='3' fill='#eae6db'/><rect x='578' y='50' width='44' height='26' rx='3' fill='#d7e3dd'/><rect x='78' y='84' width='44' height='26' rx='3' fill='#9ab8ac'/><rect x='128' y='84' width='44' height='26' rx='3' fill='#9ab8ac'/><rect x='178' y='84' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='228' y='84' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='278' y='84' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='328' y='84' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='378' y='84' width='44' height='26' rx='3' fill='#d7e3dd'/><rect x='428' y='84' width='44' height='26' rx='3' fill='#d7e3dd'/><rect x='478' y='84' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='528' y='84' width='44' height='26' rx='3' fill='#d7e3dd'/><rect x='578' y='84' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='78' y='118' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='128' y='118' width='44' height='26' rx='3' fill='#eae6db'/><rect x='178' y='118' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='228' y='118' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='278' y='118' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='328' y='118' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='378' y='118' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='428' y='118' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='478' y='118' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='528' y='118' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='578' y='118' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='78' y='152' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='128' y='152' width='44' height='26' rx='3' fill='#eae6db'/><rect x='178' y='152' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='228' y='152' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='278' y='152' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='328' y='152' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='378' y='152' width='44' height='26' rx='3' fill='#1d4e50'/><rect x='428' y='152' width='44' height='26' rx='3' fill='#5f8f7f'/><rect x='478' y='152' width='44' height='26' rx='3' fill='#eae6db'/><rect x='528' y='152' width='44' height='26' rx='3' fill='#eae6db'/><rect x='578' y='152' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='78' y='186' width='44' height='26' rx='3' fill='#9ab8ac'/><rect x='128' y='186' width='44' height='26' rx='3' fill='#9ab8ac'/><rect x='178' y='186' width='44' height='26' rx='3' fill='#9ab8ac'/><rect x='228' y='186' width='44' height='26' rx='3' fill='#c8dbd2'/><rect x='278' y='186' width='44' height='26' rx='3' fill='#9ab8ac'/><rect x='328' y='186' width='44' height='26' rx='3' fill='#d7e3dd'/><rect x='378' y='186' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='428' y='186' width='44' height='26' rx='3' fill='#eae6db'/><rect x='478' y='186' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='528' y='186' width='44' height='26' rx='3' fill='#f0ece1'/><rect x='578' y='186' width='44' height='26' rx='3' fill='#f0ece1'/><text x='16' y='222' font-size='9' fill='#6f7a7c'>公锥 / 捞矛按落物内径选型；母锥 / 卡瓦筒按落物外径选型；一把抓需落底；磁力仅铁磁性；篮式仅 0—5 mm 细碎屑。<\/text><text x='16' y='240' font-size='9' fill='#99a3a4'>套铣筒与平底磨鞋属于解卡 / 磨铣工序，不参与落物形态评分；磨铣后清屑用篮式捞筒 / 反循环。<\/text><\/svg><\/div><div class='figcap'><b>图 2<\/b><span>矩阵本身不复杂，难的是<b>把落物描述塞进某一行<\/b>：「电缆带着钢丝绳和几块碎胶皮」要拆成柔索类 + 碎屑，才能同时推荐绳类打捞钩与篮式捞筒。套铣筒与平底磨鞋是<b>解卡 / 磨铣工序<\/b>，不参与这张形态矩阵的打分。<\/span><\/div>"},{"no":3,"en":"DATA","title":"你需要准备什么","html":"<p>这份清单的特别之处在于：<b>知识表比数据量更重要<\/b>。工具台账整理得越细（尤其是「可捞区间按外径还是内径」与「最小咬合长度」这两列），推荐越准；打捞记录的作用是给每个工具一个真实的历史成功率。<\/p><div class='checklist'><div class='cl-head'><span>数据准备清单 · 4 项<\/span><span class='cl-prog'><span id='cl-txt'>0 / 4<\/span><span class='cl-bar'><i id='cl-fill'><\/i><\/span><\/div><div class='cl-item' data-cl='0'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>落物描述与图像<\/span><span class='cl-s'>形态、外径、内径、长度、材质、所在深度、落底三态、卡阻状态<\/span><\/span><span class='cl-n'>现场记录 + 井口照片<\/span><\/div><div class='cl-item' data-cl='1'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>打捞记录<\/span><span class='cl-s'>工具组合、起下钻次数、是否一次捞出<\/span><\/span><span class='cl-n'>300—1000 例<\/span><\/div><div class='cl-item' data-cl='2'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>工具台账（规格）<\/span><span class='cl-s'>适用形态、外径、内孔、可捞外径 / 内径区间、最小咬合长度、最大容纳长度、允许井斜、是否需循环、是否需落底<\/span><\/span><span class='cl-n'>知识表，11 + 2 条<\/span><\/div><div class='cl-item' data-cl='3'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>井身结构数据<\/span><span class='cl-s'>套管规格与通径（不是外径）、井斜、井温、落物以上井段状况<\/span><\/span><span class='cl-n'>作为硬约束输入<\/span><\/div><\/div>"},{"no":4,"en":"DIFFICULTY","title":"技术难度与参考方向","html":"<div style='display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:4px'><span class='dtag' data-d='中'>难度 中<\/span><span class='small muted'>难点是输入的不确定性，不是算法的复杂度<\/span><\/div><div class='meter'><i class='on'><\/i><i class='on'><\/i><\/div><p>难度定在「中」是因为<b>方法本身不复杂<\/b>（规则 + 加权评分，可解释性极好，工程师一眼能看懂为什么推荐它），但有三处必须处理干净：<b>一<\/b>，落物描述是文本，「几根断油管带一个接箍」要能抽出「管状体 / 外径 73 mm / 内径 62 mm / 长度 6 m / 落底或未知」；<b>二<\/b>，落物状态常常不确定（是否落底、是否被砂埋），这时不能只给一个答案，而要给出「首选 + 备选 + 需要先探底」的作业顺序；<b>三<\/b>，历史成功率要按井型分档统计，把 40° 井斜的成功率混进平均值里会误导推荐。<\/p><p>建议先做一个「离线选型工具」给工程师用：输入落物描述，输出推荐工具与理由，先不改现场流程；跑三个月，把工程师的选择与系统推荐做对比，把差异回写进知识表。这一步做完，命中率通常能到 80% 以上，再谈接入作业系统。<\/p><p style='margin-top:18px'><span class='kicker plain' style='color:var(--ink-4)'>可借鉴的通用技术<\/span><\/p><div class='refs'><span class='ref'>知识图谱<\/span><span class='ref'>规则匹配与打分<\/span><span class='ref'>文本信息抽取<\/span><span class='ref'>相似度检索<\/span><\/div><div class='callout'><span class='ci'>说明<\/span><span>这个案例里「智能化」的表现形式很朴素：<b>可解释的加权评分 + 一份整理干净的知识表<\/b>。它的价值不在算法新不新，而在把一段只存在于老师傅脑子里的判断逻辑，变成了新员工第一天就能用的工具。<\/span><\/div>"}]},"workflow":{"label":"案例流程","title":"从工具手册到选型工具：一个区块 640 例打捞记录的整理过程","lead":["起点是一本 60 页的打捞工具手册和一堆散落的打捞记录，终点是一个输入落物描述、输出推荐工具与作业顺序的小工具。","整个过程没有用深度学习，用的是知识表 + 加权评分；验收标准很硬：把工程师的选择当成参考答案，看工具能不能复现。"],"stats":[["打捞记录","640 例"],["打捞工具 / 工序工具","11 / 2"],["Top-1 命中","81%"],["示范默认起下钻","1 趟"]],"steps":[{"name":"落物描述结构化","role":"数据","do":"把 640 条打捞记录里的落物描述拆成 8 个字段：形态类别（管状 / 杆状 / 柔索 / 实心小件 / 工具）、外径、内径、长度、材质、是否落底、是否能循环洗井、卡阻状态。","effect":"得到 640 条可计算的输入样本，其中 92% 能完整填满 8 个字段。","trap":"「落底」这个字段现场经常没写。默认填「是」是最危险的捷径——悬空落物的推荐结果完全不同，必须回查井史或标记为「未知」，并同时保留落底 / 悬空两个分支；对外部套入式工具，还要先核对「可捞上限 &lt; 内孔 &lt; 外径」。"},{"name":"工具知识表建模","role":"知识工程","do":"把手册里每件工具写成一条记录：适用形态及权重、工具外径、内孔、可捞落物外径或内径区间、最小咬合长度 / 最大容纳长度、允许最大井斜、是否需循环、是否需落底、历史成功率（按井型分档）、备注（如「需先磨铣」）。","effect":"11 条打捞工具 + 2 条工序工具（套铣筒、平底磨鞋），就是选型算法的全部知识来源。","trap":"手册里的「适用范围」通常是定性描述（「适用于管类落物」），必须转化为可比较的数值区间与权重；公锥 / 捞矛按落物内径、母锥 / 卡瓦筒按落物外径，不能共用一个区间。"},{"name":"硬约束筛选","role":"算法","do":"按物理可行性剔除选项：工具外径 + 单边 6 mm 间隙必须小于套管内通径；落物外径 / 内径必须落在工具可捞区间；磁力打捞器只对铁磁性材料生效；井斜不得超过工具允许值；需循环的工具必须有循环条件；需落底的工具不能用于悬空落物；落物长度不得小于最小咬合长度、也不得超过工具可容纳长度。","effect":"候选从 11 项压到 0—5 项，且排除了所有「不可能成功」的方案；不可用项直接标「不可用」，不进入推荐。","trap":"环空间隙与通径要求被忽略会导致工具卡在落物上方或根本下不去——这类错误在算法里看不出来，必须来自工具工程师的确认值；用套管外径代替通径是最常见的口径错误。"},{"name":"软评分与作业顺序推荐","role":"算法核心","do":"对剩余候选按 形态 0.32 / 尺寸 0.26 / 井斜 0.16 / 历史成功率 0.16 / 工况条件 0.10 加权打分，排序后输出「首选 + 备选」，并对需要先磨铣、先探底或落物卡阻的组合给出作业顺序与工具串（打捞工具 + 震击器 + 安全接头）。","effect":"输出首选 + 备选、综合匹配度与分项理由；推荐结果可在 30 秒内说清依据。","trap":"权重需要按区块标定：老井井斜大、套管有变形时，井斜项的权重应上调，否则推荐会偏向在直井里好用的工具。"},{"name":"现场验证与知识表回写","role":"人工","do":"工程师按推荐下工具，记录实际起下钻次数与结果；每月把「工程师改选」的案例拿出来复盘，修正形态适用度矩阵与成功率。","effect":"Top-1 命中率从上线时的 68% 提升到 81%，示范默认起下钻 1 趟。","trap":"只统计成功率、不统计「为什么改选」，知识表永远不会变准。每次改选都要记一句话原因。"}],"metrics":{"title":"怎么算“做对了”","html":"<p>这个场景的评价指标要和「钱」挂钩，否则看不出价值：<\/p><table class='dtable'><thead><tr><th>指标<\/th><th>定义<\/th><th>本案例取值<\/th><\/tr><\/thead><tbody><tr><td>Top-1 命中率<\/td><td>工程师最终使用的工具即系统首选的比例<\/td><td>81%<\/td><\/tr><tr><td>平均起下钻次数<\/td><td>单井次打捞作业的起下钻趟数期望<\/td><td>示范默认 1 趟（原 2—3 趟）<\/td><\/tr><tr><td>首选未命中后果<\/td><td>首选失败时的平均额外工期<\/td><td>+1.6 天<\/td><\/tr><tr><td>危险推荐率<\/td><td>推荐方案中出现物理不可行项的比例<\/td><td>0%（硬约束拦截）<\/td><\/tr><\/tbody><\/table><p>注意最后一行：<b>危险推荐率必须是 0<\/b>。落物打捞是井下作业，一个「外径超限」的推荐可能直接把工具卡在井里，代价远大于少省一天工期。所以硬约束不能进模型，只能进规则。<\/p>"},"fails":[{"name":"「落底」状态填错","why":"悬空落物按落底处理，会推荐需要靠落底收爪的工具（一把抓等），下井后抓空，白跑一趟。"},{"name":"形态描述含糊导致双解","why":"「电缆带钢丝」既能按柔索类用绳类打捞钩，也可能需要先用篮式捞筒清碎屑，系统必须输出作业顺序而不是单一答案。"},{"name":"成功率未按井型分档","why":"把 40° 井斜的成功率混算进平均，会让井斜适应性差的工具在大斜度井里被误推荐。"}]},"demo":{"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"设定落物形态、外径 / 内径、长度、井斜、落底三态、材质与卡阻状态，看硬约束先排除哪些工具（工具外径 + 单边间隙、可捞区间、材质、井斜、循环、落底、咬合长度），软评分如何给剩下 11 件打捞工具排序；套铣筒与平底磨鞋只作为解卡 / 磨铣工序出现，不参与打捞排序。","height":760}}};

  /* 供「案例包」页使用：在线试跑 + 一键下载 zip + 复制包结构 */
  var LIB = (window.CASE_PACKS = window.CASE_PACKS || {});
